const t=[{id:1,icon:"Snowflake",accent:"#2563eb",title:"السلامة في فصل الشتاء",subtitle:"حماية النفس من البرد ومخاطر الشتاء",summary:"الشتاء فصلٌ جميل، لكنّ له مخاطره أيضًا: البرد والثلج والجليد والانزلاق والغاز السامّ المنبعث من المدافئ. علينا أن نعرف كيف نحمي أنفسنا وعائلاتنا.",blocks:[{heading:"تدفئة المنزل بأمان",body:`استخدم مدافئ الغاز والنفط والكهرباء استخدامًا صحيحًا ووفق تعليمات الشركة المصنِّعة.
• اترك منفذًا للتهوية مفتوحًا في الغرفة، لأن مدافئ الغاز والنفط تُنتج غاز أول أكسيد الكربون (CO) السامّ.
• لا تترك المدفأة مشتعلة أثناء النوم.`},{heading:"الوقاية من البرد",body:"ارتدِ ملابس دافئة على طبقات. غطِّ رأسك ويديك وقدميك جيدًا. وإذا كان الجو شديد البرودة، فلا تبقَ في الخارج مدة طويلة."},{heading:"القيادة الآمنة على الثلج والجليد",body:"قُد سيارتك ببطء على الثلج والجليد. زِد المسافة بين سيارتك والسيارة التي أمامك. استخدم إطارات شتوية أو سلاسل."},{heading:"منع تجمّد الأنابيب",body:"تتجمّد أنابيب المياه في البرد وتنفجر. لُفَّ الأنابيب الخارجية واعزلها. وفي الليالي شديدة البرودة، اترك الماء يجري ببطء وبكمية قليلة."}],tips:["ركّب جهاز إنذار لغاز أول أكسيد الكربون (CO) في المنزل","أطفئ مدفأة الغاز قبل النوم","ارتدِ الملابس على طبقات — فهي أفضل من قطعة ملابس واحدة سميكة","احتفظ بحقيبة إسعافات أولية وبطانية في السيارة","احرص على أن يكون هاتفك المحمول مشحونًا بالكامل عند خروجك"],warnings:["لا تضع المدفأة بالقرب من الستائر والملابس","أبعِد الأطفال عن المدفأة","لا تسمح بتراكم كميات كبيرة من الثلج على سطح المنزل","لا توصِل عدة مدافئ كهربائية بمقبس كهربائي واحد"],activity:{prompt:"أنت في المنزل ومدفأة الغاز مشتعلة. أحد أفراد العائلة يشكو من صداع ويشعر بالدوار. ماذا ستفعل؟",options:[{text:"أُخرج الجميع فورًا إلى الهواء الطلق (وأطفئ المدفأة في طريقي فقط إذا كان ذلك سريعًا وآمنًا)، وأتصل بالرقم 122 حتى لو بدأوا يشعرون بتحسّن، ولا يعود أحد إلى الداخل حتى تتم تهوية الغرفة وفحص المدفأة",correct:!0},{text:"أعطيه دواءً للصداع وأترك المدفأة مشتعلة",correct:!1},{text:"أطفئ المدفأة فقط ونبقى في الغرفة",correct:!1},{text:"لا أفعل شيئًا وأنتظر",correct:!1}]},quiz:[{question:"لماذا يجب أن يبقى منفذ للتهوية مفتوحًا في الغرفة عندما تكون مدفأة الغاز مشتعلة؟",options:[{text:"لكي تصبح رائحة الغرفة طيبة",correct:!1},{text:"لمنع تراكم غاز أول أكسيد الكربون (CO) السامّ",correct:!0},{text:"لكي لا تبرد الغرفة",correct:!1},{text:"لكي لا يصدر صوت",correct:!1}]},{question:"أيّ الملابس أفضل للوقاية من البرد؟",options:[{text:"قطعة ملابس واحدة سميكة",correct:!1},{text:"ملابس على طبقات",correct:!0},{text:"ملابس خفيفة",correct:!1},{text:"لا يوجد فرق",correct:!1}]},{question:"كيف نمنع تجمّد أنابيب المياه؟",options:[{text:"نلفّ الأنابيب، وفي الليالي شديدة البرودة نترك الماء يجري ببطء وبكمية قليلة",correct:!0},{text:"لا نفعل شيئًا",correct:!1},{text:"نُشعل نارًا تحت الأنابيب",correct:!1},{text:"نكسر الأنابيب",correct:!1}]}]},{id:2,icon:"Sun",accent:"#ea580c",title:"السلامة في فصل الصيف",subtitle:"حماية النفس من الحرّ وحرائق الغابات",summary:"الصيف فصلٌ حارّ تكتنفه مخاطر خاصة، مثل ضربة الشمس، واحتراق حقول الحبوب والمحاصيل، وحرائق الغابات، والغرق في المياه، وشحّ المياه. تعالَوا نتعلّم كيف نحمي أنفسنا.",blocks:[{heading:"الوقاية من ضربة الشمس (Heatstroke)",body:"اشرب الماء على مدار اليوم قبل أن تشعر بالعطش. لا تبقَ تحت أشعة الشمس في أشدّ أوقات النهار حرارة. ارتدِ ملابس خفيفة فاتحة اللون، واستخدم قبعة."},{heading:"الإنهاك الحراري أم ضربة الحرّ؟",body:`• الإنهاك الحراري (Heat exhaustion): تعرّق غزير، وجلد بارد شاحب رطب، وضعف، ودوار، وصداع، وغثيان، وعطش. انقل المصاب إلى مكان بارد، وأرخِ ملابسه، وبرّده بالماء، وأعطه رشفات من الماء إذا كان واعيًا تمامًا. اطلب المساعدة الطبية إذا تقيّأ، أو ساءت الأعراض أو استمرّت أكثر من ساعة، أو اضطرب وعيه (فهذه ضربة حرّ).
• ضربة الحرّ أو ضربة الشمس (Heatstroke): جسم شديد الحرارة مع اضطراب الوعي، أو سلوك غريب، أو تثاقل في الكلام، أو نوبة تشنّج، أو انهيار؛ وقد يكون الجلد حارًّا وجافًّا أو لا يزال متعرّقًا. وهذه حالة طارئة: اتصل بالرقم 122، وانقل المصاب إلى مكان بارد، وانزع الملابس الزائدة، وابدأ تبريده فورًا قبل نقله إلى المستشفى. وأفضل طريقة غمر الجسم حتى الرقبة في ماء بارد لمدة 15 دقيقة أو حتى يعود تفكيره واضحًا، أيّهما أسبق؛ وإن تعذّر ذلك فاستخدم دشًّا باردًا، ومناشف أو شراشف مبلّلة بماء بارد، وأكياس ثلج، مع التهوية بالمروحة. ولا تعطِ المصاب المضطرب الوعي شيئًا ليشربه.`},{heading:"الوقاية من حرائق الغابات",body:"لا تُشعل النار في الغابات وبين الأعشاب الجافة. لا ترمِ أعقاب السجائر. لا تترك الزجاجات في العراء، لأنها قد تعمل عمل العدسة فتُركّز أشعة الشمس وتُشعل النار."},{heading:"السلامة في البحيرات والأنهار",body:"لا تذهب للسباحة وحدك. اسبح فقط في الأماكن الآمنة وتحت المراقبة. ارتدِ سترة النجاة (Life jacket). لا تُبعد نظرك عن الأطفال."},{heading:"حفظ الطعام والماء",body:"يفسد الطعام بسرعة في الصيف. احفظ الطعام في الثلاجة. اشرب ماءً نظيفًا. اغسل الفواكه والخضراوات جيدًا."}],tips:["اشرب الماء على مدار اليوم — 2 لتر أو أكثر في أغلب الأحيان","لا تبقَ تحت أشعة الشمس وقت الظهيرة وبعد الظهر، حين تكون الحرارة في أعلى مستوياتها","استخدم كريم الوقاية من الشمس (SPF 30+)","تناول الفواكه الغنية بالماء (مثل البطيخ والشمّام)","لا تترك الأطفال والحيوانات وحدهم في سيارة حارّة"],warnings:["ضربة الشمس قد تكون قاتلة — أكثِر من شرب الماء وابقَ في الظل","تنتشر النار في الغابات بسرعة كبيرة","الغرق في المياه — لا تترك الأطفال دون مراقبة","الطعام الفاسد يسبّب التسمّم"],activity:{prompt:"أنت في الخارج وتشعر بالدوار والضعف. أصبح جسمك حارًّا جدًّا. ماذا ستفعل؟",options:[{text:"أنتقل إلى مكان ظليل، وأشرب الماء، وأبرّد جسمي بالماء البارد، وأتصل بالرقم 122",correct:!0},{text:"أواصل عملي",correct:!1},{text:"أبقى تحت الشمس وأشرب الماء المثلّج فقط",correct:!1},{text:"أستلقي تحت الشمس وأنام",correct:!1}]},quiz:[{question:"لماذا لا ينبغي أن نترك زجاجات الماء في الخارج تحت أشعة الشمس؟",options:[{text:"لأن الماء يسخن",correct:!1},{text:"لأنها قد تُشعل النار كما تفعل العدسة",correct:!0},{text:"لأن الزجاج ينكسر",correct:!1},{text:"لا يوجد فرق",correct:!1}]},{question:"كم ينبغي أن نشرب من الماء في الصيف؟",options:[{text:"نصف لتر يكفي",correct:!1},{text:"1 لتر يكفي",correct:!1},{text:"على مدار اليوم، 2 لتر أو أكثر",correct:!0},{text:"فقط عندما نشعر بالعطش",correct:!1}]},{question:"في أيّ وقت من النهار تكون الحرارة والمخاطر أكبر في فصل الصيف؟",options:[{text:"الصباح الباكر",correct:!1},{text:"الظهيرة وما بعد الظهر",correct:!0},{text:"المساء",correct:!1},{text:"الليل",correct:!1}]}]},{id:3,icon:"Home",accent:"#059669",title:"السلامة في المنزل",subtitle:"حماية العائلة من المخاطر داخل المنزل",summary:"ينبغي أن يكون المنزل مكانًا آمنًا للعائلة، لكنّ فيه مخاطر كثيرة، مثل الحريق والكهرباء والغاز والسقوط والتسمّم. تعالَوا نتعلّم كيف نجعل منزلنا آمنًا.",blocks:[{heading:"السلامة من الحريق ومطفأة الحريق",body:`ركّب جهاز إنذار الدخان واختبره مرة كل شهر. ضع مطفأة حريق بالقرب من المطبخ. أنواع مطفآت الحريق (حسب فئات NFPA):
• الماء: للخشب والورق والقماش (الفئة A).
• CO₂: للأجهزة الكهربائية (الفئة C).
• مسحوق ABC: للفئات A وB وC، لكن ليس لزيت الطبخ ولا للمعادن.
• الرغوة (Foam): للسوائل القابلة للاشتعال (الفئة B).
• لا تصبّ الماء أبدًا على الزيت المشتعل!

لا تستخدم المطفأة إلا إذا تحقّق كل ما يلي: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك. وإذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب. طريقة PASS: اسحب مسمار الأمان (Pull)، ووجّه فوهة الخرطوم نحو قاعدة النار (Aim)، واضغط على المقبض بقوة (Squeeze)، وحرّك الخرطوم يمينًا ويسارًا (Sweep). حدّد طريق الخروج من المنزل في حالات الطوارئ.`},{heading:"السلامة الكهربائية والمولّدات",body:`حافظ على سلامة المقابس والأسلاك الكهربائية. أصلِح الأسلاك المقطوعة أو التالفة أو استبدلها. لا تلمس الأجهزة الكهربائية بيدين مبتلّتين. لا توصِل أجهزة كثيرة بمقبس متعدد واحد.

المولّدات: شغّل المولّد في الخارج فقط، على بعد 6 أمتار (20 قدمًا) على الأقل من النوافذ والأبواب وفتحات التهوية — ولا تشغّله أبدًا داخل المنزل أو المرآب أو القبو أو المحل أو المخزن، حتى لو كانت الأبواب والنوافذ مفتوحة. ركّب في المنزل جهاز إنذار لأول أكسيد الكربون (CO) يعمل بالبطارية. ولا توصِل المولّد أبدًا بمقبس الجدار أو بأسلاك كهرباء المنزل: فقد يصعق الجيران وعمال الكهرباء. ولا يوصله إلا كهربائي مختص عبر مفتاح تحويل (Transfer Switch).`},{heading:"السلامة من الغاز",body:"افحص أنابيب الغاز وأسطواناته بانتظام. إذا شممت رائحة الغاز: لا تُشغّل أيّ مفتاح كهربائي ولا تُطفئه، ولا تُشعل النار، ولا تستخدم الهاتف داخل المنزل، ولا تشغّل مولّدًا أو سيارة في مكان قريب. افتح النوافذ والأبواب في طريقك إلى الخارج إن استطعت. لا تُغلق صمّام الغاز إلا إذا كان قريبًا ويمكن الوصول إليه بأمان، دون الدخول إلى المكان الذي تجمّع فيه الغاز؛ وإلا فلا تقترب منه. اخرج من المنزل، ونبّه الآخرين، واتصل بالرقم 115 من خارج المنزل."},{heading:"الوقاية من السقوط",body:"ركّب درابزينًا للسلالم. لا تترك الأغراض على الأرض وعلى السلالم. احرص على أن تكون إضاءة السلالم جيدة. نظّف الماء المسكوب على الأرض فورًا."}],tips:["اختبر جهاز إنذار الدخان مرة كل شهر","لا توصِل أجهزة كثيرة بالمقابس المتعددة","احفظ الأدوية والمواد الكيميائية في مكان مغلق وبعيد عن متناول الأطفال","أبقِ طريق الخروج في حالات الطوارئ مفتوحًا دائمًا","اكتب أرقام الطوارئ (115، 122، 104) في مكان ظاهر"],warnings:["لا تترك الأطفال وحدهم في المطبخ","ضع الأشياء الزجاجية والحادّة في مكان مرتفع وبعيد عن الأطفال","اجعل النوافذ والشرفات آمنة للأطفال","اللعب بالنار والكهرباء قد يكون قاتلًا"],activity:{prompt:"تشمّ رائحة غاز في المطبخ. ماذا ستفعل؟",options:[{text:"أفتح النوافذ في طريقي إلى الخارج، ولا أُغلق صمّام الغاز إلا إذا أمكن الوصول إليه بأمان، وأخرج من المنزل، وأتصل بالرقم 115 من الخارج",correct:!0},{text:"أُشعل الضوء لأرى مكان تسرّب الغاز",correct:!1},{text:"أُشغّل مصباح الهاتف المحمول داخل المنزل",correct:!1},{text:"أنتظر حتى تزول رائحة الغاز",correct:!1}]},quiz:[{question:"كم مرة يجب أن نختبر جهاز إنذار الدخان؟",options:[{text:"مرة كل 5 سنوات",correct:!1},{text:"مرة كل شهر",correct:!0},{text:"أبدًا",correct:!1},{text:"عند الشراء فقط",correct:!1}]},{question:"ماذا نفعل عندما نشمّ رائحة غاز في المنزل؟",options:[{text:"نُشعل الأضواء الكهربائية",correct:!1},{text:"نفتح النوافذ في طريقنا إلى الخارج، ولا نُغلق صمّام الغاز إلا إذا كان الوصول إليه آمنًا، ونخرج",correct:!0},{text:"نُشعل سيجارة",correct:!1},{text:"ننتظر حتى تزول الرائحة",correct:!1}]},{question:"لماذا لا يجوز لمس الكهرباء بيدين مبتلّتين؟",options:[{text:"لأن اليدين تتّسخان",correct:!1},{text:"لأن الماء يوصل الكهرباء ويسبّب صعقة كهربائية",correct:!0},{text:"لأن الكهرباء تنقطع",correct:!1},{text:"لا يوجد فرق",correct:!1}]}]},{id:4,icon:"HeartPulse",accent:"#dc2626",title:"أساسيات الإسعافات الأولية",subtitle:"إجراءات أولية لإنقاذ الحياة حتى وصول سيارة الإسعاف",summary:"يمكن للإسعافات الأولية أن تُنقذ حياة إنسان. إذا أُصيب شخص ما، أو توقّف قلبه، أو عجز عن التنفّس، فبإمكانك مساعدته حتى تصل سيارة الإسعاف. الإجراء الأول: اتصل بالرقم 122.",blocks:[{heading:"الإنعاش القلبي الرئوي (CPR) للبالغين",body:`عندما يتوقّف قلب شخص ما (يفقد الوعي ولا يتنفّس، أو لا يتنفّس بصورة طبيعية):
1. تأكّد من أن المكان آمن لك.
2. هزّ كتفيه واسأله بصوت عالٍ: «هل أنت بخير؟»
3. إذا لم يستجب، فاتصل بالرقم 122 وأرسل شخصًا ليُحضر جهاز الصدمات الكهربائية (AED).
4. اضغط 30 ضغطة على منتصف الصدر: بعمق 5-6 سم، وبمعدل 100-120 ضغطة في الدقيقة.
5. إذا كنت مدرّبًا، فأعطِ نفختين للإنقاذ (أمِل الرأس إلى الخلف، وارفع الذقن، وأغلق الأنف). وإذا لم تكن مدرّبًا أو لم ترغب في إعطاء النفخات، فاكتفِ بالضغطات الصدرية (Hands-Only CPR) دون توقّف.
6. كرّر 30:2 (أو الضغطات وحدها) حتى يصل فريق الإسعاف.

• جهاز AED: إذا كان متوفرًا، فشغّله فورًا واتّبع التعليمات الصوتية للجهاز.`},{heading:"النزيف — إيقاف الدم",body:`• الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط عليه بقوة. لا ترفع يدك حتى يتوقّف النزيف.
• إذا تشبّعت قطعة القماش بالدم، فلا تُزِلها؛ بل ضع قطعة أخرى فوقها وواصل الضغط.
• العاصبة (تورنيكيه): في حالة النزيف الشديد جدًّا من الذراع أو الساق، اربطها على بُعد 5-7 سم فوق الجرح (وليس على الركبة أو المرفق) وشدّها حتى يتوقّف النزيف. سجّل وقت وضعها ولا تُرخِها أبدًا.
• إذا كان هناك جسم مغروس في الجرح، فلا تُخرجه! اضغط حوله واتصل بالرقم 122.`},{heading:"الحروق — الإسعافات الأولية",body:`• الحرق البسيط: صُبّ الماء البارد الجاري على الحرق فورًا لمدة 20 دقيقة (لا ثلج ولا ماء شديد البرودة).
• لا تفقأ فقاعات الحرق، ولا تضع عليه الزبدة أو الزيت أو معجون الأسنان.
• بعد التبريد، غطِّ الحرق برفق بقطعة قماش نظيفة أو بغلاف بلاستيكي للطعام.
• الحرق الشديد أو الواسع: اتصل بالرقم 122. إذا كانت الملابس ملتصقة بالجلد، فلا تنزعها. حافظ على دفء جسم المصاب.`},{heading:"الاختناق بجسم غريب (Choking)",body:`العلامات: لا يستطيع الشخص الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه.
• البالغون والأطفال (من عمر سنة واحدة فما فوق): وجّه 5 ضربات بباطن راحة اليد بين لوحَي كتفيه. ثم 5 ضغطات بطنية (Heimlich): قف خلفه، وضع قبضتك فوق السرّة بقليل وأسفل عظمة القصّ بمسافة كافية، واضغط بسرعة نحو الداخل وإلى الأعلى. كرّر 5+5.
• الرضيع (أقل من سنة واحدة): ضع الرضيع على ساعدك، ووجهه إلى الأسفل ورأسه أخفض من صدره، ووجّه 5 ضربات على ظهره. ثم اقلبه على ظهره واضغط 5 ضغطات على منتصف الصدر بكعب راحة يد واحدة. لا تُجرِ أبدًا ضغطات بطنية للرضّع.
• إذا فقد الوعي، فاتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR).`}],tips:["اتصل دائمًا بالرقم 122 أولًا","استخدم القفّازات إن توفّرت","احتفظ بحقيبة إسعافات أولية في المنزل وفي السيارة","التحق بدورة في الإسعافات الأولية","الوقت مهم — ابدأ المساعدة بسرعة"],warnings:["قبل كل شيء، تحقّق من سلامتك أنت","إذا سقط شخص من مكان مرتفع، فلا تحرّكه (فقد تكون رقبته أو ظهره مصابًا)، إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR)","لا تضع أيّ شيء في فم الشخص فاقد الوعي","لا تلمس الجرح بيدين متّسختين"],activity:{prompt:"اختنق شخص في المنزل بجسم ما ولا يستطيع الكلام أو التنفّس. ماذا ستفعل؟",options:[{text:"أوجّه 5 ضربات على ظهره، ثم 5 ضغطات بطنية (Heimlich)، وأكرّر ذلك",correct:!0},{text:"أعطيه ماءً ليشربه",correct:!1},{text:"أُدخل أصابعي عميقًا في فمه",correct:!1},{text:"أنتظر حتى يتحسّن",correct:!1}]},quiz:[{question:"في الإنعاش القلبي الرئوي (CPR) للبالغين، ما نسبة الضغطات إلى الأنفاس؟",options:[{text:"10 ضغطات ونفَس واحد",correct:!1},{text:"30 ضغطة ونفَسان",correct:!0},{text:"15 ضغطة ونفَسان",correct:!1},{text:"50 ضغطة و5 أنفاس",correct:!1}]},{question:"ماذا نفعل في حالة الحرق البسيط؟",options:[{text:"نضع عليه الثلج",correct:!1},{text:"نضع عليه الزبدة",correct:!1},{text:"ماء بارد جارٍ لمدة 20 دقيقة",correct:!0},{text:"نضع عليه النفط",correct:!1}]},{question:"ما رقم الإسعاف؟",options:[{text:"115",correct:!1},{text:"122",correct:!0},{text:"104",correct:!1},{text:"911",correct:!1}]}]},{id:5,icon:"Backpack",accent:"#9333ea",title:"حقيبة الطوارئ",subtitle:"تجهيز حقيبة لحالات الطوارئ",summary:"حقيبة الطوارئ هي الحقيبة التي تحتوي على الأشياء الضرورية في حالات الطوارئ، مثل الزلزال أو الفيضان أو أيّ حادث آخر. ينبغي أن يكون لدى كل منزل حقيبة كهذه.",blocks:[{heading:"الماء والطعام",body:`• الماء: نحو 4 لترات لكل شخص يوميًّا، لمدة 3 أيام على الأقل (للشرب والنظافة).
• أطعمة معلّبة أو جافة لا تحتاج إلى طهي.
• البسكويت والتمر والحلويات.`},{heading:"المستلزمات الطبية",body:"ضمادات، وشاش نظيف للجروح، وشريط لاصق طبي، وقفّازات، ومقصّ، وملقط، والأدوية الخاصة بأفراد العائلة (إن وُجدت)."},{heading:"مستلزمات مهمة",body:"مصباح يدوي وبطاريات، وراديو صغير، وشاحن متنقّل (Power bank) لشحن الهاتف المحمول، وملابس إضافية، وبطانية، وصفّارة لطلب المساعدة."},{heading:"الوثائق والنقود",body:"نسخ من بطاقة الهوية وجواز السفر، وبعض النقود، وقائمة بالأرقام المهمة، ومفاتيح احتياطية."}],tips:["اختر حقيبة خفيفة يسهل حملها","افحص محتويات الحقيبة مرة كل 6 أشهر، واستبدل ما انتهت صلاحيته من الماء والطعام","ضع الحقيبة في مكان قريب من الباب يسهل الوصول إليه","ضع فيها أشياء خاصة بكل فرد من أفراد العائلة (الأطفال، كبار السنّ، المرضى)","لا تنسَ الحيوانات الأليفة أيضًا"],warnings:["تأكّد من أن الماء والطعام يكفيان جميع أفراد العائلة","لا تنسَ أدويتك","ضع فيها هاتفًا محمولًا وشاحنًا","النقود مهمة، لأن البطاقات المصرفية قد لا تعمل"],activity:{prompt:"بعد وقوع زلزال، يجب عليكم إخلاء المنزل بسرعة. حقيبة الطوارئ جاهزة في المنزل. ماذا ستفعل؟",options:[{text:"آخذ الحقيبة وأتوجّه إلى نقطة التجمع",correct:!0},{text:"أبحث لبعض الوقت لأجمع أشياء أخرى",correct:!1},{text:"أترك الحقيبة وأهرب فقط",correct:!1},{text:"أبقى في المنزل وأنتظر",correct:!1}]},quiz:[{question:"كم ينبغي أن يكون في حقيبة الطوارئ من الماء لكل شخص؟",options:[{text:"1 لتر يكفي",correct:!1},{text:"نحو 4 لترات يوميًّا، لمدة 3 أيام على الأقل",correct:!0},{text:"نصف لتر",correct:!1},{text:"لا يوجد فرق",correct:!1}]},{question:"كم مرة ينبغي أن نفحص محتويات الحقيبة؟",options:[{text:"مرة كل 10 سنوات",correct:!1},{text:"مرة كل 6 أشهر",correct:!0},{text:"عند الشراء فقط",correct:!1},{text:"لا تحتاج إلى فحص أبدًا",correct:!1}]},{question:"أيّ هذه الأشياء غير ضروري في حقيبة الطوارئ؟",options:[{text:"الماء",correct:!1},{text:"المصباح اليدوي",correct:!1},{text:"التلفاز",correct:!0},{text:"الأدوية",correct:!1}]}]},{id:6,icon:"PhoneCall",accent:"#16a34a",title:"أرقام الطوارئ",subtitle:"معرفة الأرقام وكيفية الاتصال",summary:"معرفة أرقام الطوارئ قد تُنقذ الأرواح. ينبغي لكل شخص أن يحفظ هذه الأرقام عن ظهر قلب، وأن يعرف متى وكيف يتصل.",blocks:[{heading:"الأرقام الرئيسية في إقليم كوردستان",body:`• 115: الدفاع المدني (الحريق، الإنقاذ، انهيار المباني، الفيضانات، تسرّب الغاز والمواد الخطرة).
• 122: الإسعاف (الحالات الطبية الطارئة).
• 104: الشرطة.`},{heading:"كيفية الاتصال",body:"حافظ على هدوئك وتحدّث بوضوح. اذكر المكان الدقيق أولًا: الحيّ، والشارع، ومَعلمًا قريبًا، والطابق. ثم اذكر ما حدث، وعدد المصابين أو المحاصَرين، وأيّ خطر (انتشار النار، الغاز، الكهرباء، المواد الكيميائية). اذكر اسمك ورقم هاتفك. أجب عن الأسئلة، واتّبع تعليماتهم، ولا تُنهِ المكالمة حتى يطلبوا منك ذلك."},{heading:"متى نتصل بأيّ رقم",body:`• الحريق، أو الدخان، أو الانفجار، أو الانهيار، أو الفيضان، أو وجود شخص محاصَر: 115.
• الإصابات، أو المرض الشديد، أو وجود شخص فاقد الوعي: 122.
• السرقة، والتهديد، والحوادث الأمنية: 104.
• إذا اجتمع حريق أو حادث مع وجود مصابين: 115 و122.`},{heading:"العنوان الصحيح",body:"اذكر اسم الحيّ والشارع، والمعالم الواضحة القريبة (مسجد، مدرسة، متجر)، ورقم المنزل ولونه."}],tips:["احفظ الأرقام في هاتفك المحمول","ضع قائمة بالأرقام في مكان ظاهر في المنزل","علّم الأطفال هذه الأرقام","علّم الأطفال عنوان المنزل","احفظ عنوان منزلك بدقة"],warnings:["لا تُجرِ أبدًا مكالمات كاذبة أو على سبيل المزاح — فهي تؤخّر وصول المساعدة إلى من يحتاجون إليها","لا تُشغل خط الطوارئ دون سبب — فحياة الآخرين في خطر","حافظ على هدوئك وتحدّث بوضوح","العنوان الصحيح مهم جدًّا"],activity:{prompt:"رأيت سيارة تصدم شخصًا في الشارع فأُصيب. ماذا ستفعل؟",options:[{text:"أتصل بالرقم 122، وأذكر العنوان، وأُبلغ عن حالة المصاب",correct:!0},{text:"أمضي في طريقي",correct:!1},{text:"أصوّر مقاطع فيديو",correct:!1},{text:"أكتفي بالمشاهدة",correct:!1}]},quiz:[{question:"ما رقم الدفاع المدني (الحريق والإنقاذ)؟",options:[{text:"122",correct:!1},{text:"104",correct:!1},{text:"115",correct:!0},{text:"911",correct:!1}]},{question:"عند الاتصال، ما المعلومات التي يجب أن تقدّمها؟",options:[{text:"اسمك فقط",correct:!1},{text:"المكان الدقيق أولًا، ثم ما حدث، وعدد المصابين أو المحاصَرين، وأيّ خطر، واسمك ورقم هاتفك",correct:!0},{text:"العنوان فقط",correct:!1},{text:"لا حاجة إلى أيّ معلومات",correct:!1}]},{question:"ما رقم الإسعاف؟",options:[{text:"115",correct:!1},{text:"122",correct:!0},{text:"104",correct:!1},{text:"100",correct:!1}]}]},{id:7,icon:"FireExtinguisher",accent:"#dc2626",title:"مطفأة الحريق — تدريب شامل",subtitle:"التعرّف على أنواع مطفآت الحريق وفئات الحريق وطريقة PASS",summary:"مطفأة الحريق (Fire Extinguisher) أداة أساسية لإخماد الحرائق الصغيرة في بدايتها. ينبغي لكل شخص بالغ في المنزل ومكان العمل أن يعرف كيف يستخدمها بسرعة وبطريقة صحيحة، لأن مطفآت الحريق اليدوية لا تعمل إلا بضع ثوانٍ. إذا كبرت النار، فاترك المطفأة، واخرج، واتصل بالرقم 115.",blocks:[{heading:"فئات الحريق (حسب NFPA)",body:`• الفئة A: المواد الصلبة العادية (الخشب، الورق، القماش).
• الفئة B: السوائل والغازات القابلة للاشتعال (البنزين، النفط، الغاز). الماء يؤدي إلى انتشار السائل المشتعل.
• الفئة C: الأجهزة الكهربائية الموصولة بالتيار. لا تستخدم الماء أو الرغوة.
• الفئة D: المعادن القابلة للاشتعال (مثل المغنيسيوم). الماء يسبّب تفاعلًا عنيفًا وانفجارًا.
• الفئة K: زيوت الطبخ ودهونه. الماء ينثر الزيت الساخن فتنتشر نار كبيرة.`},{heading:"أنواع مطفآت الحريق",body:`الفئات مكتوبة بأحرف NFPA:
• الماء: للفئة A فقط.
• CO₂: للفئة B وللأجهزة الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). مداها قصير، ولا تصلح لحرائق الخشب والورق العميقة. أمسك المقبض فقط ولا تلمس فوهة الخرطوم — فهي تبرد كثيرًا وتحرق الجلد. وفي الغرفة الصغيرة اخرج بعد الاستخدام وهوِّ المكان، لأن CO₂ يطرد الأكسجين.
• مسحوق ABC: للفئات A وB وC. ليس للفئة D ولا للفئة K.
• الرغوة: للفئتين A وB. لا تستخدمها للأجهزة الكهربائية.
• الغاز النظيف (Clean Agent): للأجهزة الحسّاسة مثل الحواسيب؛ وتختلف فئاته حسب الطراز، فاقرأ الملصق.
• المادة الكيميائية الرطبة (Wet Chemical): لزيت الطبخ (الفئة K).
• الفئة D: فقط مطفأة أو مادة يذكر ملصقها المعدن المشتعل.`},{heading:"طريقة PASS",body:`قبل استخدام المطفأة (يجب أن تكون كل الإجابات «نعم»):
• الحريق صغير وفي بدايته، مثل حريق في سلة مهملات أو مقلاة.
• المطفأة مناسبة لهذا النوع من الحريق.
• طريق الخروج خلفك، والنار ليست بينك وبين المخرج.
• تمّ إطلاق الإنذار: نُبِّه الآخرون واتُّصل بالرقم 115.
• أنت مدرَّب على استخدام المطفأة.
• لا يوجد دخان أو حرارة يمنعان خروجك.
• إذا لم تنطفئ النار فورًا، فتوقّف واخرج وأغلق الباب خلفك.

1. P = Pull (اسحب): اسحب مسمار الأمان.
2. A = Aim (وجِّه): وجِّه فوهة الخرطوم نحو قاعدة النار، لا نحو أعلاها.
3. S = Squeeze (اضغط): اضغط على مقبض المطفأة بقوة.
4. S = Sweep (حرِّك): حرِّك الخرطوم يمينًا ويسارًا حتى تنطفئ النار.

PASS هي الطريقة العامة لمعظم المطافئ اليدوية. أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والغاز النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة.`},{heading:"فحص مطفأة الحريق",body:`الفحص البصري مرة كل شهر، يجريه الشخص المسؤول:
• أن تكون المطفأة في مكانها، ظاهرة وسهلة الوصول.
• أن يكون مسمار الأمان وختمه في مكانهما.
• أن يكون الملصق مقروءًا ومتّجهًا إلى الخارج.
• ألّا يكون الخرطوم مكسورًا أو مثقوبًا، وأن تكون الفوهة غير مسدودة.
• ألّا يكون جسم المطفأة صدئًا أو متضررًا أو يسرّب.
• إذا كان فيها مؤشر ضغط، أن يكون المؤشر في المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.

خدمة يجريها فنّي مؤهَّل:
• الفحص والصيانة (Maintenance): مرة كل سنة.
• إعادة التعبئة (Recharge): بعد أي استخدام، ولو كان قصيرًا.
• صيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار ضغط كل 12 سنة، ويُفحص داخلها كل 6 سنوات.
• اختبار ضغط جسم المطفأة (Hydrostatic test): كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم.

موعد الاختبار ليس موعدًا للاستبدال. تُسحب المطفأة من الخدمة إذا فشلت في الفحص أو الاختبار، أو تضرّرت، أو صارت قديمة الطراز، أو استدعتها الشركة المصنّعة، أو لم يعد ملصقها مقروءًا، أو كانت من النوع غير القابل لإعادة التعبئة وتجاوزت مدة الخدمة المكتوبة على ملصقها. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.`},{heading:"مخاطر خاصة في المنزل والمجتمع",body:`• المطبخ: زيت الطبخ من الفئة K — استخدم مطفأة Wet Chemical أو غطاءً كبيرًا.
• الكهرباء: المقابس والأسلاك — الفئة C.
• موقد الغاز والأسطوانة: الغاز — الفئة B؛ والأولوية لإيقاف الغاز: يُغلق شخصٌ مؤهَّل صمّامَ الغاز فقط إذا كان الوصول إليه آمنًا. لا تُطفئ لهب الغاز إذا لم يمكن إيقاف الغاز بأمان: أخرِج الجميع واتصل بالرقم 115.
• البنزين والنفط: خزّنهما بعيدًا عن المنزل في مكان جيد التهوية.
• مطفأة ABC مناسبة لمعظم حرائق المنزل، لكنها ليست لزيت الطبخ (K) ولا للمعادن (D).`},{heading:"ألوان مطفآت الحريق (BS EN 3 وBS 7863)",body:`اللون ليس فئة الحريق. وفقًا للمعيار الأوروبي BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة:
• الكريمي = الرغوة.
• الأزرق = المسحوق الجاف.
• الأسود = CO₂.
• الأصفر = Wet Chemical.
• الماء بلا شريط.

وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا.`},{heading:"الفئة F (زيت الطبخ) — هي نفسها الفئة K",body:`تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. لذا فالفئة F (EN 2) والفئة K (NFPA) فئة واحدة: حرائق زيوت الطبخ ودهونه.
• الزيت شديد السخونة قد يشتعل من تلقاء نفسه.
• مطفأة Wet Chemical هي المناسبة: فهي تُكوّن طبقة شبيهة بالصابون على سطح الزيت تعزل الأكسجين وتُبرّد الزيت.
• تحتاج المطاعم والمطابخ الكبيرة إلى مطفآت حريق من الفئة F/K.`}],tips:["يجب أن تتوفّر في كل منزل مطفأة ABC واحدة على الأقل","ضع المطفأة بالقرب من باب المطبخ، لا داخل المطبخ بجوار الموقد","درّب جميع أفراد العائلة البالغين على استخدام المطفأة","افحص المطفأة مرة كل شهر؛ وإذا كان فيها مؤشر ضغط، فيجب أن يكون في المنطقة الخضراء (مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة)","لا تسحب مسمار الأمان إلا عند الحاجة","ابدأ من المسافة المحددة على ملصق المطفأة أو في تعليمات الشركة المصنّعة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار","اجعل ظهرك نحو باب الخروج — لكي يبقى طريق الهروب مفتوحًا دائمًا","سلّم المطفأة مرة كل سنة إلى شخص مختصّ لإجراء الصيانة (Service)","لا تعمل مطفأة الحريق اليدوية إلا بضع ثوانٍ — كن مستعدًّا قبل أن تبدأ"],warnings:["لا تصبّ الماء أبدًا على الزيت المشتعل — ستنتشر نار كبيرة بسرعة!","لا تستخدم الماء أبدًا على الأجهزة الكهربائية — خطر الصعق الكهربائي!","لا تستخدم المطفأة إذا كانت النار أكبر من سلة مهملات، أو كانت تنتشر، أو كان الدخان يزداد: اخرج واتصل بالرقم 115!","وجِّه فوهة الخرطوم دائمًا نحو قاعدة النار — لا نحو أعلاها!","مطفأة CO₂: لا تلمس فوهة الخرطوم! فهي تبرد إلى نحو 78 درجة تحت الصفر وتحرق الجلد.","مسحوق ABC في غرفة مغلقة يحجب الرؤية ويُصعّب التنفّس — اخرج بعد استخدامه وافتح الأبواب والنوافذ"],activity:{prompt:"في مطبخ المنزل، اشتعلت النار في الزيت داخل المقلاة على الموقد! ماذا ستفعل؟",options:[{text:"أصبّ عليها الماء",correct:!1},{text:"إذا كان ذلك آمنًا، أُطفئ الموقد وأضع عليها غطاءً كبيرًا لقطع الأكسجين، أو أستخدم مطفأة Wet Chemical",correct:!0},{text:"أحمل المقلاة وأُخرجها إلى الخارج",correct:!1},{text:"أضربها بقطعة ملابس لتنطفئ",correct:!1}]},quiz:[{question:"بأحرف NFPA، لأيّ فئات الحريق تصلح مطفأة CO₂؟",options:[{text:"A وD",correct:!1},{text:"B وC",correct:!0},{text:"A وK",correct:!1},{text:"D وK",correct:!1}]},{question:"في طريقة PASS، إلى أين يجب توجيه فوهة الخرطوم؟",options:[{text:"أعلى النار",correct:!1},{text:"قاعدة النار",correct:!0},{text:"حول النار",correct:!1},{text:"سقف الغرفة",correct:!1}]},{question:"لماذا لا يُصبّ الماء على حريق الزيت (الفئة K)؟",options:[{text:"لأنه لا تأثير له",correct:!1},{text:"لأن الماء يتحوّل بسرعة إلى بخار فينثر الزيت الساخن وتنتشر نار كبيرة",correct:!0},{text:"لأن الزيت يمتصّ الماء",correct:!1},{text:"لأن الماء نفسه يحترق",correct:!1}]},{question:"أيّ مطفأة تناسب معظم حرائق المنزل (الفئات A وB وC)؟",options:[{text:"مطفأة الماء",correct:!1},{text:"مطفأة CO₂",correct:!1},{text:"مطفأة مسحوق ABC",correct:!0},{text:"مطفأة الرغوة",correct:!1}]},{question:"وفق ترميز الألوان البريطاني (BS EN 3 مع BS 7863)، ما لون الشريط على مطفأة Wet Chemical (لزيت الطبخ)؟",options:[{text:"أحمر",correct:!1},{text:"أسود",correct:!1},{text:"أصفر",correct:!0},{text:"أزرق",correct:!1}]},{question:"وفقًا لـ NFPA 10، كم مرة يجب أن يُجري شخص مختصّ الصيانة (Maintenance) لمطفأة الحريق؟",options:[{text:"كل أسبوع",correct:!1},{text:"مرة كل سنة، مع فحص بصري كل شهر",correct:!0},{text:"مرة كل 20 سنة",correct:!1},{text:"لا تحتاج إلى فحص",correct:!1}]}]},{id:8,icon:"Heart",accent:"#db2777",title:"الإسعافات الأولية والإنعاش القلبي الرئوي (CPR)",subtitle:"تدريب شامل على الإسعافات الأولية وإنعاش القلب",summary:"الإسعافات الأولية (First Aid) هي المساعدة الأولية التي تُقدَّم للشخص المصاب أو المريض قبل وصول الفريق الطبي. ينبغي لكل فرد في المجتمع أن يعرف كيف يُجري الإنعاش القلبي الرئوي (CPR)، ويوقف النزيف، ويحمي المصاب حتى تصل سيارة الإسعاف. هذا الدرس قد يحمي حياتك وحياة عائلتك.",blocks:[{heading:"الإنعاش القلبي الرئوي (CPR) — إنعاش القلب والرئتين",body:`1. تحقّق من سلامة المكان.
2. هزّ كتفي المصاب واسأله: «هل أنت بخير؟»
3. إذا لم يستجب ولم يكن يتنفّس بصورة طبيعية، فاتصل بالرقم 122 واطلب جهاز الصدمات الكهربائية (AED).
4. اضغط 30 ضغطة على منتصف الصدر: بمعدل 100-120 ضغطة في الدقيقة، وبعمق 5-6 سم لجميع البالغين.
5. إذا كنت مدرّبًا ومستعدًّا، فأعطِ نفختين، مدة كل منهما ثانية واحدة. وإذا لم تكن مدرّبًا أو لم ترغب في إعطاء النفخات، فاكتفِ بالضغطات الصدرية (Hands-Only CPR) دون توقّف.
6. واصل 30:2 (أو الضغطات وحدها) حتى يصل فريق الإسعاف.
7. إذا توفّر جهاز AED، فاستخدمه فورًا.`},{heading:"إيقاف النزيف",body:`• الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط عليه بقوة.
• إذا تشبّعت قطعة القماش بالدم، فلا تُزِلها؛ بل ضع قطعة أخرى فوقها وواصل الضغط.
• العاصبة (تورنيكيه): في حالة النزيف الشديد جدًّا من الذراع أو الساق، اربطها على بُعد 5-7 سم فوق الجرح، وسجّل وقت وضعها، ولا تُرخِها أبدًا.
• لا تُخرج الجسم المغروس في الجرح!`},{heading:"علاج الحروق",body:`• الحروق الحرارية: ماء بارد جارٍ لمدة 20 دقيقة.
• الحروق الكيميائية: اغسلها بكمية كبيرة من الماء، لمدة 20 دقيقة على الأقل.
• الحروق الكهربائية: الإجراء الأول هو قطع التيار الكهربائي! ثم اتصل بالرقم 122.
• لا تفقأ فقاعات الحرق، ولا تستخدم الزبدة أو الزيت أو معجون الأسنان.`},{heading:"الكسور والسقوط",body:`• لا تحرّك العضو المصاب — ثبّته بعصا أو لوح خشبي (جبيرة - Splint).
• لا تحرّك الشخص الذي سقط من مكان مرتفع: فقد تكون رقبته أو ظهره مصابًا. أبقِه ثابتًا واتصل بالرقم 122. لا تحرّكه إلا إذا كان المكان خطرًا (حريق، أو حركة مرور، أو انهيار، أو غاز، أو ارتفاع المياه)، مع إبقاء الرأس والرقبة والظهر على خط واحد. وإذا احتاج إلى الإنعاش القلبي الرئوي (CPR)، فمدّده على ظهره على سطح صلب. ولا تضعه على جنبه في وضعية الإفاقة.
• لُفَّ الثلج بقطعة قماش وضعه على التورّم.`},{heading:"الصعقة الكهربائية",body:`• اقطع التيار الكهربائي فورًا! لا تلمس المصاب قبل قطع التيار.
• إذا لم تستطع قطع التيار (في كهرباء المنازل فقط)، فأبعِد السلك عن المصاب بعصا خشبية جافة.
• اتصل بالرقم 122؛ إذ يجب أن يخضع كل من تعرّض لصعقة كهربائية لفحص طبي.`},{heading:"الاختناق بجسم غريب — طريقة Heimlich",body:`إذا كان الشخص لا يستطيع الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه، فهو مختنق بجسم غريب.
• وجّه 5 ضربات بباطن راحة اليد بين لوحَي كتفيه.
• 5 ضغطات بطنية (Heimlich): قف خلفه، وضع قبضتك فوق السرّة بقليل وأسفل عظمة القصّ بمسافة كافية، وأمسكها باليد الأخرى، واضغط بسرعة نحو الداخل وإلى الأعلى.
• واصل 5+5 حتى يخرج الجسم أو يفقد الشخص وعيه؛ فإذا فقد وعيه، فاتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR).
• الرضيع (أقل من سنة واحدة): 5 ضربات على الظهر (ورأسه أخفض من صدره) و5 ضغطات على الصدر. لا تُجرِ أبدًا ضغطات بطنية للرضّع.`},{heading:"وضعية الإفاقة (Recovery Position)",body:`إذا كان الشخص فاقدًا للوعي لكنه يتنفّس بصورة طبيعية، ولم يُشتبه في إصابة رقبته أو ظهره، فضعه في وضعية الإفاقة:
1. ضع ذراعه القريبة منك بزاوية قائمة باتجاه الرأس.
2. ضع ذراعه البعيدة على صدره، واجعل ظهر يده تحت خدّه.
3. ارفع ركبة ساقه البعيدة.
4. أمسك الركبة والكتف، واقلبه نحوك على جانبه.
5. أمِل رأسه قليلًا إلى الخلف ليبقى مجرى الهواء مفتوحًا.

• اتصل بالرقم 122 وراقب تنفّسه حتى تصل سيارة الإسعاف.`}],tips:["يجب أن تتوفّر في كل منزل حقيبة إسعافات أولية","ضع قائمة أرقام الطوارئ في مكان ظاهر","علّم جميع أفراد العائلة الإنعاش القلبي الرئوي (CPR) وطريقة Heimlich","احرص على وجود قماش نظيف وعاصبة (تورنيكيه) ومقصّ في الحقيبة","الرقم 122 متاح دائمًا — لا تخف واتصل","الدماغ يتضرّر سريعًا دون أكسجين — ابدأ الإنعاش القلبي الرئوي (CPR) بسرعة","لجميع البالغين، بمن فيهم كبار السنّ، عمق الضغط 5-6 سنتيمترات — لا تُقلّله","للمرأة الحامل أو الشخص شديد البدانة، عند الاختناق بجسم غريب، اضغط على منتصف الصدر لا على البطن"],warnings:["لا تلمس المصاب إذا لم يُقطع التيار الكهربائي!","لا تُخرج الجسم المغروس في الجرح!","لا تفقأ فقاعات الحرق!","لا تحرّك الشخص الذي سقط من مكان مرتفع، إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR)!","لا تستخدم الضغطات البطنية (Heimlich) للرضّع الذين تقلّ أعمارهم عن سنة واحدة!","واصل الإنعاش القلبي الرئوي (CPR) حتى يصل فريق الإسعاف — لا تتوقّف"],activity:{prompt:"اشتعلت النار في يد أحد أصدقائك وأُصيب بحرق كبير. ماذا ستفعل؟",options:[{text:"أضع على الحرق الزبدة أو الزيت",correct:!1},{text:"أصبّ الماء البارد الجاري على الحرق لمدة 20 دقيقة وأتصل بالرقم 122",correct:!0},{text:"أفقأ فقاعات الحرق",correct:!1},{text:"لا أفعل شيئًا",correct:!1}]},quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، كم ضغطة يجب أن تُعطى على الصدر في الدقيقة؟",options:[{text:"50-70",correct:!1},{text:"80-90",correct:!1},{text:"100-120",correct:!0},{text:"150 فأكثر",correct:!1}]},{question:"إذا كان هناك جسم حادّ مغروس في الجرح، فماذا ستفعل؟",options:[{text:"أُخرجه",correct:!1},{text:"أتركه في مكانه وأتصل بالرقم 122",correct:!0},{text:"أتركه وأمضي في طريقي",correct:!1},{text:"أغسله بالماء وأُخرجه",correct:!1}]},{question:"إذا تعرّض شخص لصعقة كهربائية، فما الإجراء الأول؟",options:[{text:"أُمسك بيده",correct:!1},{text:"أبدأ الإنعاش القلبي الرئوي (CPR) فورًا",correct:!1},{text:"أقطع التيار الكهربائي",correct:!0},{text:"أصبّ عليه الماء",correct:!1}]},{question:"ما العلامة الرئيسية للاختناق التامّ بجسم غريب؟",options:[{text:"صوت عالٍ يصدر من الحلق",correct:!1},{text:"العجز عن الكلام والسعال والتنفّس، مع وضع اليدين على الحلق",correct:!0},{text:"سعال خفيف",correct:!1},{text:"صداع",correct:!1}]},{question:"لمن تُستخدم وضعية الإفاقة (Recovery Position)؟",options:[{text:"الشخص فاقد الوعي الذي لا يزال يتنفّس بصورة طبيعية",correct:!0},{text:"الشخص فاقد الوعي الذي لا يتنفّس",correct:!1},{text:"الشخص الواعي المصاب بجرح بسيط",correct:!1},{text:"شخص سليم لا يعاني من أيّ مشكلة",correct:!1}]}]},{id:9,icon:"CarFront",accent:"#2563eb",title:"السلامة المرورية",subtitle:"حماية النفس والعائلة على الطرق",summary:"تُعدّ الحوادث المرورية من أكبر أسباب الوفاة والإصابة. إن تعلّم قوانين المرور والالتزام بها قد يحمي حياتك. يتناول هذا الدرس سلامة المشاة والسائقين والأطفال.",blocks:[{heading:"سلامة المشاة",body:"امشِ دائمًا على الرصيف. قبل عبور الشارع، انظر إلى الاتجاهين واعبر من ممرّ المشاة. لا تنظر إلى هاتفك المحمول أثناء العبور. في الليل، ارتدِ ملابس فاتحة اللون أو ملابس عليها علامات عاكسة للضوء (Reflective)."},{heading:"سلامة القيادة",body:"اربط حزام الأمان دائمًا. لا تستخدم الهاتف المحمول أثناء القيادة. التزم بسرعة مناسبة ووفق القانون. استخدم في الشتاء إطارات مناسبة."},{heading:"الأطفال في السيارة",body:"أجلِس الأطفال دائمًا على مقعد الأطفال الخاص (Car seat) المناسب لأعمارهم وأوزانهم. يجلس الأطفال بعمر 12 سنة فما دون في المقاعد الخلفية. لا تترك الأطفال وحدهم في السيارة أبدًا."},{heading:"الدراجات النارية والهوائية",body:"ارتدِ خوذة الحماية (Helmet) دائمًا. في الليل، لا بدّ من الأضواء والعلامات العاكسة للضوء. ارتدِ قفّازات وأحذية مناسبة."}],tips:["اربط حزام الأمان دائمًا","لا تستخدم الهاتف المحمول أثناء القيادة","يجلس الأطفال في المقاعد الخلفية","خوذة الحماية للدراجات النارية والهوائية"],warnings:["الهاتف المحمول + القيادة = خطر الموت","السرعة + الثلج أو الجليد = حادث"],activity:{prompt:"أنت تقود السيارة ويرنّ هاتفك المحمول. وصلتك رسالة مهمة. ماذا ستفعل؟",options:[{text:"أواصل القيادة وأقرأ الرسالة",correct:!1},{text:"أتوقّف في مكان آمن على جانب الطريق ثم أردّ",correct:!0},{text:"أستخدم الهاتف بيد واحدة",correct:!1},{text:"أكتب الردّ بسرعة أثناء القيادة",correct:!1}]},quiz:[{question:"الأطفال بعمر كم سنة فما دون يجب أن يجلسوا في المقاعد الخلفية للسيارة؟",options:[{text:"12 سنة",correct:!0},{text:"6 سنوات",correct:!1},{text:"18 سنة",correct:!1},{text:"لا يوجد فرق",correct:!1}]},{question:"أيّ هذه الأفعال يُعدّ من أخطر الأفعال أثناء القيادة؟",options:[{text:"استخدام الهاتف المحمول",correct:!0},{text:"ربط حزام الأمان",correct:!1},{text:"القيادة بالسرعة القانونية",correct:!1},{text:"التوقّف عند إشارة المرور الحمراء",correct:!1}]}]},{id:10,icon:"LifeBuoy",accent:"#0891b2",title:"السلامة المائية والوقاية من الغرق",subtitle:"حماية النفس والأطفال بالقرب من المياه",summary:"وفقًا لمنظمة الصحة العالمية (WHO)، يُعدّ الغرق في المياه أحد الأسباب الرئيسية لوفاة الأطفال والشباب في العالم. وفي إقليم كوردستان، تكون البحيرات والسدود والأنهار خطيرة جدًّا في الصيف. إن تعلّم السلامة المائية ضروري لجميع العائلات.",blocks:[{heading:"الأطفال والماء",body:"لا تترك الأطفال وحدهم بالقرب من الماء أبدًا — فالطفل الصغير قد يغرق في كمية قليلة جدًّا من الماء (بضعة سنتيمترات، كما في دلو أو طست). وبالقرب من الأحواض والمياه، أبقِ عينيك عليهم دائمًا."},{heading:"السباحة بأمان",body:"اسبح فقط في الأماكن الرسمية وتحت المراقبة. ليكن معك شخص آخر دائمًا. اعرف عمق الماء قبل النزول إليه. ارتدِ سترة النجاة (Life jacket) في البحيرات والأنهار."},{heading:"الإنقاذ",body:`إذا كان شخص ما يغرق في الماء:
1. لا تنزل إلى الماء بنفسك!
2. مُدَّ إليه شيئًا أو ارمِه له (حبل، عصا، طوق نجاة).
3. اتصل بالرقمين 115 و122.
4. بعد إخراجه من الماء، افحص تنفّسه. إذا لم يكن يتنفّس بصورة طبيعية وكنت مدرّبًا، فابدأ الإنعاش القلبي الرئوي (CPR) مع النفخات: ففي الغرق يتوقّف التنفّس أولًا، ولذلك فالنفخات هي الأهم. وإذا لم تكن مدرّبًا أو لم تستطع إعطاء النفخات، فاكتفِ بالضغطات الصدرية حتى وصول المساعدة.
5. كل من أُخرج من الماء يجب أن يفحصه طبيب، حتى لو بدا بخير، لأن مشكلات الرئة شائعة بعد ذلك.`}],tips:["لا تترك الأطفال وحدهم بالقرب من الماء","ارتدِ سترة النجاة (Life jacket) في البحيرات والأنهار","لا تنزل إلى الماء لإنقاذ أحد — ارمِ له شيئًا","تعلّم الإنعاش القلبي الرئوي (CPR)"],warnings:["بضعة سنتيمترات من الماء تكفي لإغراق طفل صغير","قد تكون مياه الأنهار والسدود في الإقليم شديدة التيار وباردة جدًّا، حتى لو بدت هادئة من السطح"],activity:{prompt:"أنت وعائلتك بالقرب من بحيرة. يريد طفلك الصغير أن ينزل إلى الماء. ماذا ستفعل؟",options:[{text:"أتركه يذهب — هذا أمر عادي",correct:!1},{text:"أُلبسه سترة النجاة، وأرافقه، وأراقبه عن قرب",correct:!0},{text:"أطلب منه البقاء على الشاطئ وأبتعد عنه",correct:!1},{text:"أراقبه من بعيد",correct:!1}]},quiz:[{question:"إذا كان شخص ما يغرق في الماء، فما الإجراء الأول؟",options:[{text:"أنزل إلى الماء لأنقذه",correct:!1},{text:"أرمي له شيئًا (حبلًا أو عصا) وأتصل بالرقمين 115 و122",correct:!0},{text:"أكتفي بالصراخ",correct:!1},{text:"لا أفعل شيئًا",correct:!1}]}]},{id:11,icon:"Activity",accent:"#d97706",title:"الزلزال في المنزل والمجتمع",subtitle:"الاستعداد والاستجابة",summary:"يأتي الزلزال دون إنذار. إن استعداد العائلات ومعرفتها بالإجراء الصحيح أثناء الزلزال يحميان الأرواح. ومنطقتنا ليست بمنأى عن خطر الزلازل، ولذلك يجب أن تكون جميع العائلات مستعدّة.",blocks:[{heading:"أثناء الزلزال",body:`1. انخفض، واحتمِ، وتمسّك (Drop, Cover, Hold On): ادخل تحت طاولة متينة وأمسك بقائمتها.
2. ابتعد عن النوافذ والزجاج والأشياء الثقيلة.
3. لا تركض إلى الخارج، ولا تقف تحت إطار الباب، ولا تستخدم المصعد.
4. إذا كنت في الخارج: ابتعد عن المباني والأشجار وأسلاك الكهرباء.`},{heading:"حقيبة الطوارئ",body:"ينبغي لكل عائلة أن تجهّز حقيبة طوارئ: ماء (نحو 4 لترات لكل شخص يوميًّا، لمدة 3 أيام على الأقل)، وطعام لا يفسد، وأدوية، وراديو يعمل بالبطاريات، ومصباح يدوي، وبطانية، ووثائق مهمة."},{heading:"بعد الزلزال",body:"إذا شممت رائحة الغاز أو سمعت صوت تسرّبه: لا تلمس أيّ مفتاح ولا تُشعل نارًا، وافتح النوافذ في طريقك إلى الخارج، ولا تُغلق صمّام الغاز إلا إذا كان قريبًا ويمكن الوصول إليه بأمان، ثم اخرج واتصل بالرقم 115 من الخارج. لا تدخل المباني المتضرّرة. توقّع حدوث الهزّات الارتدادية (Aftershock). إذا بقي أشخاص تحت الأنقاض أو كان هناك مصابون، فاتصل بالرقمين 115 و122."}],tips:["انخفض، واحتمِ، وتمسّك","أبقِ حقيبة الطوارئ جاهزة دائمًا","لا تقطع الغاز إلا إذا شممت رائحته أو سمعت صوت تسرّبه، وكان الوصول إلى الصمّام آمنًا","لا تبقَ في المباني المتضرّرة"],warnings:["لا تركض أثناء الهزّة!","لا تدخل المباني المتضرّرة!"],activity:{prompt:"يضرب زلزال قوي. أنت في المنزل والأطفال خائفون. ماذا ستفعل؟",options:[{text:"ندخل مع الأطفال تحت طاولة متينة، ونغطّي رؤوسنا، ونمسك بقائمة الطاولة",correct:!0},{text:"نركض إلى الخارج",correct:!1},{text:"نقف بجانب النافذة",correct:!1},{text:"ننزل بالمصعد",correct:!1}]},quiz:[{question:"ما الإجراء الأول أثناء الزلزال في المنزل؟",options:[{text:"ادخل تحت طاولة متينة وغطِّ رأسك",correct:!0},{text:"اركض إلى الخارج",correct:!1},{text:"قف بجانب النافذة",correct:!1},{text:"استخدم المصعد",correct:!1}]}]},{id:12,icon:"Siren",accent:"#dc2626",title:"عمل الدفاع المدني",subtitle:"مهامّ فرق 115 وكيف يمكنك مساعدتها",summary:"الدفاع المدني جهاز حكومي مهم يحمي أرواح المواطنين والممتلكات الخاصة والعامة. في إقليم كوردستان، الرقم 115 هو رقم الدفاع المدني للحرائق والإنقاذ والكوارث، وفرقه جاهزة ليلًا ونهارًا. ينبغي أن يعرف المواطنون كيف يتصلون بالرقم 115 وكيف يساعدون الفرق، لا أن يعرقلوا عملها.",blocks:[{heading:"المهامّ الرئيسية للدفاع المدني",body:`• إطفاء الحرائق: في المنازل والدوائر الحكومية والمصانع والحقول والغابات.
• الإنقاذ: من السيارات في الحوادث، ومن تحت الأنقاض، ومن المياه.
• الفيضانات والكوارث: نقل السكان، وسحب المياه، ومساعدة المتضرّرين.
• المواد الخطرة (HazMat): تسرّب الغاز والمواد الكيميائية.
• التدريب والتوعية: دروس في المدارس والدوائر الحكومية.
• التفتيش على السلامة: في الأسواق والمطاعم والقاعات والمباني العالية.`},{heading:"الهيكل الرسمي",body:`• في إقليم كوردستان، يتبع الدفاع المدني وزارة الداخلية.
• في كل محافظة مديرية للدفاع المدني، مثل مديرية الدفاع المدني في دهوك، ولها مراكز في المدن والأقضية.
• الأقسام العاملة: إطفاء الحرائق، والإنقاذ، والإسعافات الأولية، والتدريب، والأقسام الفنية.
• في الكوارث الكبرى، يعمل الدفاع المدني جنبًا إلى جنب مع الإسعاف (122) والشرطة (104) والجهات الأخرى.`},{heading:"معدّاتهم ومركباتهم",body:`• سيارات الإطفاء: تحمل الماء والخراطيم والمضخّات.
• سيارات السلالم: تصل إلى الطوابق العالية.
• معدّات الإنقاذ: أدوات هيدروليكية لقطع حديد السيارات وإخراج الأشخاص المحاصَرين (Jaws of Life).
• جهاز التنفّس (BA — Breathing Apparatus): يزوّد رجل الإطفاء بالهواء النقي وسط الدخان.
• ملابس خاصة للحماية من الحرارة.
• أجهزة راديو للاتصال بين الفرق.`},{heading:"كيف تتصل بالرقم 115",body:`1. اطلب الرقم 115.
2. حافظ على هدوئك وتحدّث بوضوح.
3. اذكر: العنوان الصحيح (الحيّ، والشارع، ومَعلمًا واضحًا قريبًا)، وما الذي حدث (حريق؟ حادث؟ شخص محاصَر؟)، وعدد المصابين أو المحاصَرين، وأيّ خطر خاص (غاز، مواد كيميائية، كهرباء)، واسمك ورقم هاتفك ليتمكّنوا من معاودة الاتصال بك.
4. لا تُنهِ المكالمة حتى يطلبوا منك ذلك.
5. إذا كان ذلك آمنًا، فأبقِ الطريق مفتوحًا أمام سيارات الإطفاء.
6. أرسل شخصًا إلى الشارع ليُرشد الفريق إلى المكان.`},{heading:"كيف يساعد المجتمع فرق 115",body:`• على الطريق: عندما تسمع صوت صفّارة الإنذار، انتقل بهدوء إلى الجانب الأيمن وتوقّف ليبقى الطريق مفتوحًا.
• لا تُجرِ مكالمات كاذبة: كل مكالمة كاذبة تُبعد فريقًا عن حالة طوارئ حقيقية.
• أبقِ طرق الوصول مفتوحة: لا توقف السيارات أمام الأبواب وفي الأزقّة الضيقة.
• الشهادة: إذا رأيت الحادث، فابقَ في المكان وقدّم معلوماتك للفريق.
• لا تتجمهر بالقرب من الفريق ولا تلتقط الصور، حتى لا تعرقل طريقهم.
• إذا طلب الفريق المساعدة، فساعِده.
• إذا رأيت أن هناك حاجة إلى 115، فلا تتأخّر — اتصل.
• حافظ على هدوئك ولا تنشر الخوف والفوضى.`},{heading:"العمل والتطوّع في الدفاع المدني",body:`• يُقدَّم طلب التعيين عبر الإعلانات الرسمية للدفاع المدني.
• تحدّد المديرية شروط العمر والتحصيل الدراسي واللياقة البدنية والاختبارات — وللاطّلاع على أحدث المعلومات، اتصل بمديرية الدفاع المدني في دهوك.
• يتلقّى الموظفون الجدد تدريبًا أساسيًّا في مجالات إطفاء الحرائق والإنقاذ والإسعافات الأولية.
• يمكن للمواطنين المشاركة في دروس التوعية والتدريبات، وأن يكونوا عونًا في أحيائهم في أوقات الطوارئ.`}],tips:["احفظ الرقم 115 — وليحفظه جميع أفراد العائلة أيضًا","اعرف عنوان منزلك بدقة (الحيّ، الشارع، رقم المنزل)","عندما تسمع صوت صفّارة الإنذار، انتقل إلى الجانب الأيمن وتوقّف، لا في منتصف الطريق","استخدم الرقم 115 لحالات الطوارئ فقط، ليبقى خطّه مفتوحًا لمن يحتاجون إليه","إذا اشتبهت في وجود حريق أو خطر، فاتصل — فمن الأفضل أن يأتي الفريق ولا تكون هناك مشكلة","اجعل رقم المنزل واسم الحيّ ظاهرين على الباب ليصل الفريق إليك بسهولة","اكتب خطة الإخلاء من المنزل وجرّبها مع عائلتك"],warnings:["لا تُجرِ مكالمات كاذبة إلى الرقم 115 — فهي تُضيّع وقت الفرق وتعرّض الأرواح للخطر","لا تتجمهر بالقرب من مركبات 115 ولا تلتقط الصور — فهذا يعرقل عملهم","لا تصوّر مقاطع فيديو للضحايا ولا تنشرها — احترم كرامتهم","عندما تسمع صفّارة الإنذار، لا تقُد سيارتك خلف مركبات الطوارئ، وأبقِ الطريق مفتوحًا أمامها"],activity:{prompt:"وقع حادث سيارة أمام منزلك. هناك شخصان محاصَران داخل السيارة ولا يوجد أحد غيرك في المكان. ماذا ستفعل؟",options:[{text:"أتصل فورًا بالرقمين 115 و122 وأذكر العنوان الصحيح. إذا لم يكن هناك حريق، فلا أُخرج المصابين المحاصَرين حتى لا تتضرّر رقابهم وظهورهم. أبقى في مكان آمن وأتّبع تعليمات 115.",correct:!0},{text:"أحاول بسرعة إخراج المصابين المحاصَرين",correct:!1},{text:"أصوّر مقطع فيديو وأنشره على مواقع التواصل الاجتماعي",correct:!1},{text:"أذهب لأبحث عن شخص آخر يساعد ولا أتصل",correct:!1}]},quiz:[{question:"ما رقم الطوارئ الخاص بالدفاع المدني في إقليم كوردستان؟",options:[{text:"991",correct:!1},{text:"107",correct:!1},{text:"115",correct:!0},{text:"122",correct:!1}]},{question:"ماذا تفعل عندما ترى سيارة إطفاء تُطلق صفّارة الإنذار؟",options:[{text:"أنتقل بهدوء إلى الجانب الأيمن وأتوقّف ليبقى الطريق مفتوحًا",correct:!0},{text:"أقود خلفها بسرعة",correct:!1},{text:"أسدّ الطريق أمامها",correct:!1},{text:"أصوّر مقاطع فيديو",correct:!1}]},{question:"عند الاتصال بالرقم 115، ما أهمّ شيء يجب أن تذكره أولًا؟",options:[{text:"اسمك فقط",correct:!1},{text:"العنوان وما الذي حدث",correct:!0},{text:"أقول «تعالوا بسرعة» وأُنهي المكالمة",correct:!1},{text:"أسأل متى سيصلون",correct:!1}]},{question:"ما وظيفة جهاز BA (Breathing Apparatus)؟",options:[{text:"هو مطفأة حريق",correct:!1},{text:"هو جهاز تنفّس يزوّد رجل الإطفاء بالهواء النقي وسط الدخان",correct:!0},{text:"هو جهاز راديو",correct:!1},{text:"هو صفّارة إنذار",correct:!1}]},{question:"إذا اجتمع حريق ومصابون، فبأيّ رقم تتصل؟",options:[{text:"104 فقط",correct:!1},{text:"122 فقط",correct:!1},{text:"115 و122",correct:!0},{text:"لا أتصل وأنتظر",correct:!1}]}]},{id:13,icon:"FlameKindling",accent:"#ea580c",title:"أنواع الحرائق",subtitle:"ليست كل الحرائق متشابهة — فكل نوع يتطلّب إجراءً خاصًّا",summary:"وفقًا للنظام الأمريكي (NFPA 10)، هناك خمس فئات للحريق: A وB وC وD وK. تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F. في كل فئة تحترق مادة مختلفة، وتتطلّب مطفأة حريق مناسبة. واختيار المطفأة الخاطئة قد يزيد النار اشتعالًا. سيعلّمك هذا الدرس كيف تتعرّف على نوع الحريق وما الذي تستخدمه.",blocks:[{heading:"الفئة A — المواد الصلبة (الخشب، الورق، القماش)",body:`شائعة جدًّا في المنزل: الورق، والكرتون، والستائر، والقماش، والبلاستيك، والأثاث الخشبي. المطفأة: الماء أو مسحوق ABC. صوّب على قاعدة النار، وابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك.
• إذا اشتعلت النار في ملابسك: توقّف، وانبطح على الأرض، وتدحرج (Stop, Drop, Roll).`},{heading:"الفئة B — السوائل والغازات القابلة للاشتعال (البنزين، النفط، الكحول)",body:`تشتعل هذه السوائل بسرعة، ويمكن لأبخرتها أن تشتعل من مسافة بعيدة. لا تستخدم الماء: فالماء ينشر السائل المشتعل ويزيد النار اتساعًا. المطفأة للسوائل: الرغوة (Foam) أو CO₂ أو مسحوق ABC. انشر الرغوة برفق على سطح السائل لتغطّيه.
• الكحول والأسيتون والمذيبات القطبية الأخرى: CO₂ أو مسحوق ABC أو الرغوة المقاومة للكحول (AR foam)، لأن الرغوة العادية تنهار عليها.
• حريق الغاز (غاز LPG أو الغاز الطبيعي): الأولوية لإيقاف تدفق الغاز. يُغلق شخصٌ مؤهَّل صمّامَ الغاز فقط إذا كان الوصول إليه آمنًا. لا تُطفئ لهب الغاز إذا لم يمكن إيقاف الغاز بأمان، فالغاز غير المحترق يتجمّع وقد ينفجر. وإذا لم يكن ذلك آمنًا، فأخلِ الجميع، وأطلق الإنذار، واتصل بالرقم 115. والرغوة ليست الخيار العام لحرائق الغاز. وفي EN 2 يُعدّ حريق الغاز من الفئة C.
• BLEVE: إذا سخّنت النار أسطوانة غاز أو خزّانًا، فقد ينفجر انفجارًا كبيرًا — ابتعد عنه واتصل بالرقم 115.`},{heading:"الفئة C — الأجهزة الكهربائية (حسب NFPA)",body:`الحواسيب، والتلفزيونات، والثلاجات، والمقابس، والأسلاك الكهربائية.
• لا تستخدم الماء أبدًا! فالصعقة الكهربائية قد تقتل.
• الإجراء الأول: اقطع التيار الكهربائي (انزع القابس أو اقطع الكهرباء الرئيسية للمنزل)، ثم استخدم CO₂ أو الغاز النظيف (Clean Agent) أو مسحوق ABC.
• مسحوق ABC يُتلف الأجهزة الإلكترونية؛ وCO₂ أفضل للأجهزة الحسّاسة.
• في النظام الأوروبي (EN 2)، لا يُعدّ حريق الكهرباء فئة مستقلة.`},{heading:"الفئة D — المعادن القابلة للاشتعال (المغنيسيوم، التيتانيوم، الصوديوم، الليثيوم المعدني)",body:`تحترق هذه المعادن بحرارة عالية جدًّا.
• لا تستخدم الماء أو CO₂ على المعادن المشتعلة — فهما يسبّبان تفاعلًا عنيفًا ونارًا أكبر.
• استخدم فقط مطفأة أو مادة يذكر ملصقها هذا المعدن، فالمادة تختلف من معدن لآخر (فالليثيوم مثلًا يحتاج مادة مخصّصة لليثيوم). ولا تستخدم الماء أو المسحوق العادي أو الرغوة أبدًا. ولا يُستخدم الرمل الجاف إلا إذا نصّت عليه خطة الحريق في الموقع أو صحيفة SDS للمعدن وكان جافًا تمامًا. واتصل بالرقم 115.
• بطاريات الليثيوم أيون (Li-ion) في الهواتف المحمولة والحواسيب المحمولة والشواحن المتنقّلة والدراجات الكهربائية لا تحتوي على الليثيوم المعدني، وليست من الفئة D: إذا اشتعلت، فبرّدها بكمية كبيرة من الماء واتصل بالرقم 115. الفئة D مخصّصة فقط لبطاريات الليثيوم المعدني (Lithium-metal).`},{heading:"الفئة K (NFPA) / F (EN 2) — زيت الطبخ",body:`حريق الزيت الساخن في المقلاة أو القِدر على الموقد.
• لا تستخدم الماء أبدًا! فالماء يتحوّل بسرعة إلى بخار داخل الزيت الساخن وينثر الزيت المشتعل بشكل انفجاري.
• مسحوق ABC لا يناسب هذه الفئة.
• استخدم مطفأة المادة الكيميائية الرطبة (Wet Chemical)، أو أطفئ الموقد وضع غطاءً كبيرًا أو بطانية الحريق (Fire blanket) لقطع الأكسجين.
• لا تحمل المقلاة ولا تُخرجها إلى الخارج.`},{heading:"مراحل تطوّر الحريق",body:`1. البداية (Incipient): النار صغيرة والدخان قليل. في هذه المرحلة فقط يكون استخدام مطفأة الحريق آمنًا.
2. النموّ (Growth): تزداد الحرارة وتنتشر النار.
3. الحريق الكامل (Fully Developed): الغرفة كلها مشتعلة.
4. الخمود (Decay): تخفّ النار، لكن إذا دخل الهواء إلى الغرفة فجأة، فهناك خطر الانفجار الارتدادي للنار (Backdraft).

• Flashover (الاشتعال الوميضي): عندما تصل حرارة طبقة الدخان الساخن تحت السقف إلى نحو 500-600 درجة مئوية، تشتعل جميع محتويات الغرفة في وقت واحد.`}],tips:["قبل الشراء، اقرأ فئات الحريق المكتوبة على ملصق مطفأة الحريق","احرص على وجود مطفأة ABC واحدة على الأقل في المنزل، ومطفأة Wet Chemical أو بطانية حريق للمطبخ","وفقًا لـ NFPA 10، لا تزيد مسافة الوصول إلى مطفأة الفئة A في أماكن العمل على 23 مترًا","وفقًا لـ NFPA، الطبخ هو السبب الأول لحرائق المنازل — لا تغادر المطبخ أثناء الطهي","حريق الأجهزة الكهربائية: لا تستخدم الماء أبدًا — الإجراء الأول هو قطع التيار الكهربائي","بطارية الليثيوم أيون: إذا سخنت أو انتفخت أو خرج منها دخان، فضعها بعيدًا عن المواد القابلة للاشتعال، وابتعد عنها، واتصل بالرقم 115","زيت الطبخ: أطفئ الموقد وضع غطاءً كبيرًا على الإناء — فهذه هي الطريقة الأولى لإخماد هذا الحريق"],warnings:["الماء على الزيت المشتعل = انفجار بخاري ونار كبيرة","الماء على الأجهزة الكهربائية = صعقة قاتلة","مسحوق ABC على الحاسوب = تلف الجهاز","برّد بطارية الليثيوم أيون المشتعلة بكمية كبيرة من الماء واتصل بالرقم 115 — فقد تشتعل النار من جديد","حريق أكبر من سلّة المهملات = اخرج فورًا، لا تستخدم المطفأة"],activity:{prompt:"أنت في المطبخ. اشتعلت النار في الزيت داخل المقلاة والموقد لا يزال مشتعلًا. عائلتك في غرفة النوم. ماذا ستفعل؟",options:[{text:"أُطفئ الموقد، وأضع غطاءً كبيرًا على المقلاة، وأُنبّه العائلة، وإذا لم تنطفئ النار نخرج ونتصل بالرقم 115",correct:!0},{text:"أصبّ عليها الماء لتبرد",correct:!1},{text:"أحمل المقلاة وأُخرجها إلى الخارج",correct:!1},{text:"أهرب وحدي ولا أُنبّه العائلة",correct:!1}]},quiz:[{question:"اشتعلت النار في حاسوب في غرفتك. ما الإجراء الصحيح؟",options:[{text:"الماء",correct:!1},{text:"أقطع التيار الكهربائي أولًا، ثم أستخدم CO₂ أو الغاز النظيف (Clean Agent) أو ABC",correct:!0},{text:"الرغوة (AFFF Foam)",correct:!1},{text:"Wet Chemical",correct:!1}]},{question:"اشتعلت النار في زيت المقلاة على موقد الغاز. ما الإجراء الأول؟",options:[{text:"أصبّ عليها الماء",correct:!1},{text:"أغلق صمّام الغاز وأضع عليها غطاءً كبيرًا",correct:!0},{text:"أرشّ عليها مسحوق ABC",correct:!1},{text:"أضربها بقطعة قماش",correct:!1}]},{question:"اشتعلت بطارية الليثيوم أيون في هاتف محمول. ماذا ستفعل؟",options:[{text:"أغطّيها ببطانية وأتركها في الغرفة",correct:!1},{text:"أرشّ عليها مسحوق ABC فقط وأذهب",correct:!1},{text:"إذا كان ذلك آمنًا، أُبعدها عن المواد القابلة للاشتعال، وأبرّدها بكمية كبيرة من الماء، وأتصل بالرقم 115",correct:!0},{text:"أرشّ عليها CO₂ فقط وأتركها",correct:!1}]},{question:"يحدث Flashover (الاشتعال الوميضي) عندما تصل حرارة طبقة الدخان الساخن تحت السقف إلى نحو كم درجة؟",options:[{text:"200 درجة مئوية",correct:!1},{text:"300 درجة مئوية",correct:!1},{text:"500-600 درجة مئوية",correct:!0},{text:"1000 درجة مئوية",correct:!1}]},{question:"وفقًا لـ NFPA، ما النشاط الذي يُعدّ السبب الأول لحرائق المنازل؟",options:[{text:"قراءة الكتب",correct:!1},{text:"غسل الملابس يدويًّا",correct:!1},{text:"الطبخ (المطبخ)",correct:!0},{text:"النوم",correct:!1}]}]},{id:14,icon:"FireExtinguisher",accent:"#0891b2",title:"كيف تستخدم مطفأة الحريق",subtitle:"أنواع مطفآت الحريق، وطريقة PASS، ومتى يجب أن تترك المطفأة وتخرج",summary:"توجد مطفآت الحريق في المنازل والدوائر الحكومية والأماكن العامة، لكن كثيرًا من الناس لا يعرفون كيف يستخدمونها. فمطفأة الحريق اليدوية لا تعمل إلا بضع ثوانٍ، ولذلك يجب أن تكون مستعدًّا قبل وقوع الحريق. يعلّمك هذا الدرس طريقة PASS، واختيار المطفأة المناسبة، والأهمّ من ذلك كلّه — متى يجب ألّا تستخدم المطفأة وأن تخرج.",blocks:[{heading:"الأنواع الرئيسية لمطافئ الحريق",body:`الفئات بأحرف NFPA:
• الماء: الفئة A فقط.
• الرغوة (Foam): A وB.
• CO₂: الفئة B والأجهزة الكهربائية الموصولة بالتيار (الفئتان B وC في NFPA؛ أما في EN 2 فالفئة C هي الغاز، ولا تُصنَّف مطفأة CO₂ لحرائق الغاز). مداها قصير؛ ولا تصلح لحرائق الخشب والورق العميقة؛ وفي الغرفة الصغيرة اخرج بعد الاستخدام وهوِّ المكان.
• مسحوق ABC: A وB وC — الأكثر انتشارًا؛ ليس للفئة D ولا للفئة K.
• المادة الكيميائية الرطبة (Wet Chemical): K، زيت الطبخ.
• الغاز النظيف (Clean Agent): للأجهزة الإلكترونية الحسّاسة؛ وتختلف فئاته حسب الطراز، فاقرأ الملصق.

اللون ليس فئة الحريق. وفق BS EN 3 يكون جسم المطفأة أحمر، وفي بريطانيا يدلّ شريط ملوّن (BS 7863) على المادة: الكريمي = الرغوة، الأزرق = المسحوق الجاف، الأسود = CO₂، الأصفر = Wet Chemical، والماء بلا شريط. وتستخدم دول أخرى ألوانًا مختلفة، ولم تُؤكَّد بعدُ الألوان المتّبعة في دهوك، لذا اقرأ الملصق ورموز الفئات دائمًا.

تُكتب الفئات هنا بأحرف NFPA 10 كمرجع للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ما يقابلها في EN 2: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.

للمنزل: مطفأة ABC، ومطفأة Wet Chemical أو بطانية حريق للمطبخ.`},{heading:"PASS — خطوة بخطوة",body:`قبل أن تبدأ، يجب أن تكون كل الإجابات «نعم»: الحريق صغير وفي بدايته، والمطفأة مناسبة، وطريق الخروج خلفك، وتمّ إطلاق الإنذار والاتصال بالرقم 115، وأنت مدرَّب، ولا يوجد دخان أو حرارة يمنعان خروجك.

1. P = Pull (اسحب): اسحب مسمار الأمان.
2. A = Aim (وجِّه): وجِّه فوهة الخرطوم نحو قاعدة النار، لا نحو أعلاها. ابدأ من المسافة المحددة على ملصق المطفأة، ولا تقترب إلا كلما صغرت النار.
3. S = Squeeze (اضغط): اضغط على المقبض بقوة وباستمرار.
4. S = Sweep (حرِّك): حرِّك الخرطوم يمينًا ويسارًا ببطء حتى تنطفئ النار.

• إذا لم تنطفئ النار فورًا، فاخرج وأغلق الباب.
• تفرغ المطافئ الصغيرة بسرعة، غالبًا خلال ثوانٍ قليلة؛ ومدة التفريغ الدقيقة مكتوبة على الملصق.
• PASS هي الطريقة العامة لمعظم المطافئ اليدوية. أما مطافئ الفئة D والمادة الكيميائية الرطبة (Wet Chemical) والغاز النظيف (Clean Agent) والمطافئ ذات العجلات فتُستخدم وفق الملصق وتعليمات الشركة المصنّعة.`},{heading:"مكان الوقوف — السلامة قبل كل شيء",body:`اجعل ظهرك دائمًا نحو الباب (طريق الخروج). ابدأ من المسافة المحددة على ملصق المطفأة أو في تعليمات الشركة المصنّعة، ولا تقترب إلا كلما صغرت النار. إذا اشتدّت الحرارة، فتراجع إلى الخلف. لا تسمح أبدًا بأن تصبح النار بينك وبين الباب.
• الدخان والحرارة قد يقتلان بسرعة — إذا امتلأت الغرفة بالدخان، فاخرج فورًا.`},{heading:"متى لا تستخدم مطفأة الحريق",body:`• النار أكبر من سلّة مهملات أو تنتشر بسرعة.
• الغرفة تمتلئ بالدخان.
• لا تعرف ما المادة التي تحترق.
• طريق الخروج ليس خلفك.
• لم يتصل أحد بالرقم 115 بعد (اتصل أولًا).
• النار تقترب من أسطوانة غاز أو خزّان سوائل.
• انتشرت السوائل القابلة للاشتعال على مساحة واسعة.

في جميع هذه الحالات: اخرج أولًا، ثم اتصل بالرقم 115.`},{heading:"فحص مطفأة الحريق في المنزل",body:`كل شهر (فحص بصري، يجريه الشخص المسؤول):
1. أن تكون المطفأة في مكانها وظاهرة، والطريق إليها مفتوحًا.
2. أن يكون مسمار الأمان وختمه سليمين.
3. أن يكون جسم المطفأة نظيفًا، خاليًا من الصدأ والكسور والتسرّب، وأن يكون الخرطوم والفوهة غير مسدودين.
4. أن يكون ملصق التعليمات سهل القراءة ومتّجهًا إلى الخارج.
5. إذا كان فيها مؤشر ضغط، أن يكون المؤشر في المنطقة الخضراء. مطفأة CO₂ ليس لها مؤشر ضغط: ارفعها لتتأكد من أنها ممتلئة.

خدمة يجريها فنّي مؤهَّل:
• الفحص والصيانة (Maintenance): مرة كل سنة، وتسجيلها على بطاقة المطفأة.
• إعادة التعبئة (Recharge): بعد أي استخدام، ولو كان قصيرًا.
• صيانة السنوات الست: تُفرَّغ مطافئ المسحوق الجاف ذات الضغط المخزَّن (stored-pressure) التي تحتاج إلى اختبار ضغط كل 12 سنة، ويُفحص داخلها كل 6 سنوات.
• اختبار ضغط جسم المطفأة (Hydrostatic test): كل 5 سنوات لمطافئ الماء والرغوة (AFFF) وCO₂ والمسحوق الجاف ذات الجسم من الفولاذ المقاوم للصدأ؛ وكل 12 سنة لمطافئ المسحوق الجاف ذات الضغط المخزَّن التي جسمها من الفولاذ الطري أو النحاس الأصفر الملحوم أو الألمنيوم.

موعد الاختبار ليس موعدًا للاستبدال. تُسحب المطفأة من الخدمة إذا فشلت في الفحص أو الاختبار، أو تضرّرت، أو صارت قديمة الطراز، أو استدعتها الشركة المصنّعة، أو لم يعد ملصقها مقروءًا، أو كانت من النوع غير القابل لإعادة التعبئة وتجاوزت مدة الخدمة المكتوبة على ملصقها. ولم تُؤكَّد بعدُ القواعد المعمول بها في دهوك.`},{heading:"أين نضع مطفأة الحريق؟",body:`• في المنزل (واحدة على الأقل): بالقرب من باب المطبخ، وفي كل طابق إن أمكن.
• في أماكن العمل (NFPA 10): لا تزيد مسافة الوصول إلى المطفأة على 23 مترًا للفئة A، و9 أو 15 مترًا للفئة B (حسب حجم المطفأة).
• يجب أن تكون علامة المطفأة (Sign) ظاهرة من بعيد.
• علّق المطفأة على الحائط على ارتفاع يسهل الوصول إليه (لا يزيد ارتفاع أعلاها على نحو 1.5 متر)، لا على الأرض ولا داخل الخزائن المغلقة.`}],tips:["للشراء: مطفأة ABC تستطيع حملها واستخدامها (وزنها مكتوب على الملصق) للمنزل، ومطفأة Wet Chemical أو بطانية حريق للمطبخ","قبل الشراء، تحقّق من فئات الحريق وعلامة المعيار (مثل EN 3) على الملصق","جرّب طريقة PASS في تدريب باستخدام مطفأة تدريبية","اقرأ على الملصق كم ثانية تعمل مطفأتك — فمعظم المطفآت الصغيرة تفرغ بسرعة","شارك في تدريبات الدفاع المدني عندما تُقام في حيّك أو مكان عملك","ابدأ من المسافة المحددة على ملصق المطفأة، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار","اجعل ظهرك دائمًا نحو الباب"],warnings:["لا تعمل المطفأة الصغيرة إلا بضع ثوانٍ — كن مستعدًّا","فوهة خرطوم مطفأة CO₂ تبرد كثيرًا — لا تلمسها","مسحوق ABC على الحاسوب قد يُلحق الضرر بالجهاز","النار أكبر من سلّة مهملات = اخرج، لا تستخدم المطفأة","بطارية الليثيوم أيون: مسحوق ABC وCO₂ لا يوقفان النار تمامًا — برّدها بكمية كبيرة من الماء واتصل بالرقم 115"],activity:{prompt:"أنت في المنزل. في غرفة النوم، اشتعلت النار في شاحن الهاتف المحمول الموصول بالمقبس الكهربائي. النار صغيرة ولديك مطفأتان في متناول يدك: مطفأة ABC بوزن 2 كغ ومطفأة Wet Chemical. ماذا ستفعل؟",options:[{text:"أقطع التيار الكهربائي أولًا (أنزع القابس إذا كان ذلك آمنًا، أو أقطع الكهرباء الرئيسية). أُنبّه عائلتي وأتصل بالرقم 115. ثم، وظهري نحو الباب، آخذ مطفأة ABC وأستخدم طريقة PASS، بدءًا من المسافة المحددة على ملصقها؛ وإذا لم تنطفئ النار فورًا، أخرج وأغلق الباب.",correct:!0},{text:"أستخدم مطفأة Wet Chemical",correct:!1},{text:"أصبّ عليها الماء",correct:!1},{text:"أهرب ولا أُنبّه أحدًا",correct:!1}]},quiz:[{question:"في طريقة PASS، إلامَ يرمز الحرف P؟",options:[{text:"Push (ادفع)",correct:!1},{text:"Pull (اسحب مسمار الأمان)",correct:!0},{text:"Point (أشِر)",correct:!1},{text:"Press (اضغط)",correct:!1}]},{question:"كم تعمل تقريبًا مطفأة صغيرة بمسحوق ABC (2 كغ)؟",options:[{text:"3-5 دقائق",correct:!1},{text:"بضع ثوانٍ فقط؛ والمدة الدقيقة مكتوبة على ملصقها",correct:!0},{text:"1 دقيقة",correct:!1},{text:"بلا حدّ",correct:!1}]},{question:"كيف تعرف من أيّ مسافة تبدأ عن النار؟",options:[{text:"ابدأ دائمًا من مسافة نصف متر",correct:!1},{text:"من ملصق المطفأة: ابدأ من المسافة المحددة عليه، وطريق الخروج خلفك، ولا تقترب إلا كلما صغرت النار",correct:!0},{text:"ابدأ دائمًا من مسافة 7-10 أمتار",correct:!1},{text:"لا يوجد فرق",correct:!1}]},{question:"متى يجب ألّا تستخدم المطفأة وأن تخرج؟",options:[{text:"أبدًا — استخدمها دائمًا",correct:!1},{text:"عندما تكون النار أكبر من سلّة مهملات أو تمتلئ الغرفة بالدخان",correct:!0},{text:"في المطبخ فقط",correct:!1},{text:"في غرفة النوم فقط",correct:!1}]},{question:"أيّ مطفأة تناسب حريق زيت الطبخ؟",options:[{text:"الماء",correct:!1},{text:"مسحوق ABC",correct:!1},{text:"Wet Chemical (الفئة K/F)",correct:!0},{text:"CO₂",correct:!1}]}]},{id:15,icon:"HeartHandshake",accent:"#e11d48",title:"الإسعافات الأولية للمواطنين",subtitle:"الفحص الأولي، وCPR، وAED، والنزيف، والحروق، والاختناق",summary:"يمكن أن تُنقَذ حياة إنسان على يد مواطن عادي إذا عرف ما الذي يجب فعله. فبعد توقّف القلب، كل دقيقة تمرّ دون إنعاش قلبي رئوي (CPR) ودون جهاز صدمات كهربائية (AED) تُقلّل فرصة النجاة. ووفقًا لإرشادات AHA 2025، يشرح هذا الدرس الفحص الأولي (DRABC)، والإنعاش القلبي الرئوي (CPR)، وجهاز الصدمات الكهربائية (AED)، وطريقة Heimlich، وإيقاف النزيف، والحروق، وبعض حالات الطوارئ الأخرى. ينبغي لكل مواطن أن يتعلّم هذه المعلومات.",blocks:[{heading:"DRABC — الفحص الأولي",body:`• D = Danger (الخطر): هل هناك خطر؟ كهرباء، أو حريق، أو حركة مرور؟ قبل كل شيء، احمِ سلامتك.
• R = Response (الاستجابة): هزّ كتفيه واسأله بصوت عالٍ: «هل أنت بخير؟» إذا لم يستجب، فاتصل بالرقم 122 واطلب جهاز AED.
• A = Airway (مجرى الهواء): أمِل الرأس إلى الخلف وارفع الذقن.
• B = Breathing (التنفّس): في مدة لا تزيد على 10 ثوانٍ، انظر هل يتحرّك الصدر وهل التنفّس طبيعي أم لا.
• C = CPR: إذا لم يكن يتنفّس بصورة طبيعية، فابدأ ضغطات الصدر فورًا. لا يحتاج المواطن إلى فحص النبض (Pulse).`},{heading:"CPR — 30:2 أو باليدين فقط (Hands-Only)",body:`• الموضع: منتصف الصدر، يد فوق الأخرى، وذراعاك مستقيمتان.
• البالغون (بمن فيهم كبار السنّ): العمق 5-6 سم، والمعدل 100-120 ضغطة في الدقيقة.
• 30 ضغطة + نفختان إذا كنت مدرّبًا؛ وإلا فاكتفِ بالضغطات (Hands-Only). والأطفال والرضّع والغرقى بحاجة خاصة إلى النفخات: إذا كنت مدرّبًا وقادرًا، فأجرِ الإنعاش مع النفخات؛ وإن لم تستطع، فالضغطات وحدها أفضل من لا شيء.
• لا تتوقّف حتى يصل جهاز AED، أو يتسلّم فريق الإسعاف العمل، أو تعجز عن الاستمرار.
• الطفل (من عمر سنة واحدة حتى سنّ البلوغ): بيد واحدة أو باليدين، والعمق نحو 5 سم (ثلث عمق الصدر).
• الرضيع (أقل من سنة واحدة): بالإبهامين مع إحاطة الصدر باليدين، أو بكعب راحة يد واحدة؛ والعمق نحو 4 سم. لم تعد طريقة الإصبعين تُدرَّس (AHA 2025).
• للأطفال والرضّع، إذا أجرى شخصان الإنعاش القلبي الرئوي (CPR) معًا: 15:2.`},{heading:"AED — جهاز الصدمات الكهربائية (Defibrillator)",body:`يتوفّر جهاز AED في الأماكن العامة مثل الدوائر الحكومية والمستشفيات والأسواق الكبيرة. يمكن لأيّ شخص استخدامه، لأن الجهاز يعطي التعليمات صوتيًّا. واستخدامه المبكر يزيد فرصة النجاة كثيرًا.
1. شغّل الجهاز.
2. ضع اللاصقتين على الصدر العاري، كما في الصورة الموجودة على اللاصقتين.
3. استمع إلى تعليمات الجهاز الصوتية.
4. نادِ بصوت عالٍ: «لا يلمسه أحد!»
5. إذا طلب الجهاز ذلك، فاضغط زرّ الصدمة.
6. تابع الإنعاش القلبي الرئوي (CPR) فورًا لمدة دقيقتين واتّبع تعليمات الجهاز.

• أثناء الصدمة، لا يلمس أحدٌ المصاب!`},{heading:"Heimlich — الاختناق بجسم غريب",body:`العلامات: لا يستطيع الشخص الكلام أو السعال أو التنفّس، ويُمسك حلقه بيديه.
1. وجّه 5 ضربات بباطن راحة اليد بين لوحَي الكتفين (Back blows).
2. ثم 5 ضغطات بطنية (Heimlich): ضع قبضتك فوق السرّة بقليل وأسفل عظمة القصّ بمسافة كافية، واضغط بسرعة نحو الداخل وإلى الأعلى.
3. كرّر 5+5 حتى يخرج الجسم؛ فإذا فقد الوعي، فاتصل بالرقم 122 وابدأ الإنعاش القلبي الرئوي (CPR).

• الرضيع (أقل من سنة واحدة): 5 ضربات على الظهر (ورأسه أخفض من صدره) + 5 ضغطات على الصدر. لا تُجرِ ضغطات بطنية أبدًا.
• المرأة الحامل أو الشخص شديد البدانة: اضغط على منتصف الصدر، لا على البطن.`},{heading:"النزيف — Stop the Bleed",body:`1. الضغط المباشر: ضع قطعة قماش نظيفة على الجرح واضغط بقوة وباستمرار. إذا تشبّعت قطعة القماش بالدم، فلا تُزِلها؛ بل ضع قطعة أخرى فوقها.
2. حشو الجرح (Wound packing): إذا كان الجرح عميقًا، فاحشُ داخله بشاش الجروح النظيف (Gauze) ثم اضغط بقوة.
3. العاصبة (تورنيكيه): في حالة النزيف المهدِّد للحياة من الذراع أو الساق، اربطها على بُعد 5-7 سم فوق الجرح (وليس على الركبة أو المرفق) وشدّها حتى يتوقّف النزيف. سجّل وقت وضعها، ولا تُرخِها ولا تنزعها أبدًا — فالفريق الطبي وحده هو من ينزعها.

• لا تُخرج الجسم الحادّ من الجرح!
• إصابة العين: لا تضغط على العين.
• جرح الرأس: إذا اشتبهت في كسر عظم الجمجمة، فاضغط برفق.
• اتصل بالرقم 122.`},{heading:"الحروق وحالات طوارئ أخرى",body:`• الحروق: 20 دقيقة من الماء البارد الجاري (لا ماء ساخن ولا ثلج).
• الإغماء (Fainting): مدّده على ظهره وارفع ساقيه قليلًا.
• مريض السكّري (Diabetic): إذا كان واعيًا ويستطيع البلع، فأعطه شيئًا حلوًا.
• نوبة الهلع (Panic attack): حافظ على هدوئك وساعده على التنفّس ببطء.
• إصابة الرأس أو الرقبة: لا تحرّكه، وأبقِه ثابتًا، واتصل بالرقم 122. لا تحرّكه إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR)، مع إبقاء الرأس والرقبة والظهر على خط واحد. ولا تضعه على جنبه في وضعية الإفاقة.
• الكسر (Fracture): لا تحرّك العضو، وثبّته، وضع ثلجًا ملفوفًا على التورّم.
• الصعقة الكهربائية: الإجراء الأول هو قطع التيار الكهربائي.
• لدغة الأفعى (Snake bite): ابتعد عن الأفعى، وأبقِ المصاب هادئًا وساكنًا. ثبّت الذراع أو الساق الملدوغة بجبيرة ولا تحرّكها، وانزع الخواتم والساعة والملابس الضيقة قبل أن يحدث التورّم. اتصل بالرقم 122 وانقله إلى المستشفى بسرعة. لا تجرح مكان اللدغة ولا تمصّه، ولا تربط رباطًا ضيقًا أو عاصبة (تورنيكيه)، ولا تضع عليه ثلجًا، ولا تستعمل العلاجات الشعبية أو العشبية.
• التسمّم: اتصل بالرقم 122، واحتفظ بعبوة المادة السامة أو ملصقها لتريها للأطباء. لا تحاول إحداث القيء، ولا تعطه حليبًا أو زيتًا أو ماءً مالحًا أو أي علاج منزلي آخر، ولا تعطه شيئًا يأكله أو يشربه إلا إذا طلب الطبيب ذلك. وإذا ابتلع النفط (الكيروسين) أو البنزين أو زيت المصابيح، فالقيء خطير جدًا لأن المادة قد تدخل إلى الرئتين. وإذا أصابت المادة السامة الجلد أو العينين، فاغسلها بكمية وافرة من الماء الجاري وانزع الملابس الملوّثة. وإذا كان المصاب نعسانًا أو فاقدًا للوعي لكنه يتنفّس طبيعيًا، فضعه على جنبه.`}],tips:["122 للإسعاف و115 للحريق والإنقاذ — احفظهما","التحق بدورة في الإنعاش القلبي الرئوي (CPR) والإسعافات الأولية، وجدّدها كل بضع سنوات","اعرف أماكن أجهزة AED القريبة من منزلك ومكان عملك","بعد توقّف القلب، كل دقيقة مهمة — ابدأ الإنعاش القلبي الرئوي (CPR) بسرعة","أغنية «Stayin' Alive» تُذكّرك بإيقاع 100-120 ضغطة في الدقيقة","احتفظ بحقيبة إسعافات أولية في المنزل وفي السيارة وفي مكان العمل","في حقيبة الإسعافات الأولية: قماش نظيف، وقفّازات، وعاصبة (تورنيكيه)، ومقصّ، وقائمة بأرقام الطوارئ"],warnings:["لا تلمس أبدًا الشخص المصاب بصعقة كهربائية قبل قطع التيار","إذا اشتبهت في إصابة الظهر أو الرقبة، فلا تحرّك الشخص الذي سقط، إلا إذا كان المكان خطرًا أو احتاج إلى الإنعاش القلبي الرئوي (CPR)","العاصبة (تورنيكيه): سجّل وقت وضعها، ولا تُرخِها ولا تنزعها أبدًا","لا تضع على الحرق ماءً ساخنًا أو ثلجًا أو زبدة أو معجون أسنان","يجب ألّا تتداخل لاصقتا جهاز AED؛ وللأطفال الأصغر من 8 سنوات، استخدم لاصقات الأطفال إن توفّرت"],activity:{prompt:"في الشارع، رأيت شخصًا عمره 55 عامًا يسقط. لا يستجيب ولا يتنفّس. يوجد جهاز AED عند باب دائرة حكومية قريبة، وهناك شخص آخر في المكان. ماذا ستفعل؟",options:[{text:"أتأكّد من أن المكان آمن وأتحقّق من استجابته. أتصل بالرقم 122 وأرسل الشخص الآخر ليُحضر جهاز AED. أبدأ فورًا الإنعاش القلبي الرئوي (CPR) بنسبة 30:2، وأستخدم جهاز AED عند وصوله.",correct:!0},{text:"أكتفي بإرسال شخص ليُحضر جهاز AED وأنتظر دون إنعاش قلبي رئوي (CPR)",correct:!1},{text:"أعطيه ماءً",correct:!1},{text:"أصوّر مقطع فيديو من بعيد",correct:!1}]},quiz:[{question:"في الإنعاش القلبي الرئوي (CPR)، ما عمق الضغط للبالغين؟",options:[{text:"2 سم",correct:!1},{text:"5-6 سم",correct:!0},{text:"10 سم",correct:!1},{text:"لا يوجد فرق",correct:!1}]},{question:"مَن يستطيع استخدام جهاز AED؟",options:[{text:"الأطباء فقط",correct:!1},{text:"أيّ شخص — فالجهاز يعطي التعليمات صوتيًّا",correct:!0},{text:"رجال الإطفاء فقط",correct:!1},{text:"لا أحد خارج المستشفى",correct:!1}]},{question:"كيف يُجرى الإنعاش القلبي الرئوي (CPR) للرضّع (أقل من سنة واحدة)؟",options:[{text:"باليدين، كما للبالغين",correct:!1},{text:"بالإبهامين (مع إحاطة الصدر باليدين) أو بكعب راحة يد واحدة، والعمق نحو 4 سم",correct:!0},{text:"بإصبعين، 2 سم",correct:!1},{text:"لا يُجرى الإنعاش القلبي الرئوي (CPR) للرضّع",correct:!1}]},{question:"بعد وضع العاصبة (تورنيكيه)، ماذا يجب أن تفعل؟",options:[{text:"أُرخيها بعد 10 دقائق",correct:!1},{text:"أسجّل وقت وضعها ولا أُرخيها أبدًا حتى يصل الفريق الطبي",correct:!0},{text:"أفكّها كل نصف ساعة ثم أربطها من جديد",correct:!1},{text:"أنزعها فورًا عندما يتوقّف النزيف",correct:!1}]},{question:"رضيع عمره أقل من سنة واحدة اختنق بجسم غريب ولا يزال واعيًا. ماذا تفعل؟",options:[{text:"ضغطات بطنية (Heimlich) فورًا",correct:!1},{text:"5 ضربات على الظهر + 5 ضغطات على الصدر",correct:!0},{text:"إنعاش قلبي رئوي (CPR) فورًا",correct:!1},{text:"أتركه وحده",correct:!1}]}]}],e={lessons:t};export{e as default,t as lessons};
